function parseFx(t){const o={};String(t||'').split(/[;,\n]/).forEach(p=>{const m=p.split('=');if(m.length!==2)return;const k=m[0].trim(),v=+m[1].trim();if(k&&m[1].trim()!==''&&isFinite(v))o[k]=v;});return o;}
function parseHab(t){const r={sel:{},opt:{},shift:{},mut:1};t.split('\n').forEach(line=>{line=line.replace(/#.*/,'').trim();if(!line)return;let m;
 if(m=line.match(/^opt\s+(\S+)\s+([-+]?[\d.]+)\s+([\d.]+)/i))r.opt[m[1]]={z:+m[2],w:Math.max(.01,+m[3])};
 else if(m=line.match(/^shift\s+(\S+)\s+([-+]?[\d.]+)/i))r.shift[m[1]]=+m[2];
 else if(m=line.match(/^mut\s+([\d.]+)/i))r.mut=+m[1];
 else if(m=line.match(/^([A-Za-z0-9_]+\^\S+)\s*=?\s*([-+]?[\d.]+)/))r.sel[m[1]]=+m[2];});return r;}
function habEff(h){const bt=biomeOf(h.type);const R=parseHab((bt&&bt.rules?bt.rules+'\n':'')+(h.rules||''));/* 類型規則（同類型共用）＋棲息地特有規則 */const E=IDX.env;const e={sel:{...R.sel},opt:{},dev:{...R.shift},plast:{},pen:{},epi:{},mut:R.mut,z:{},calc:{}};
 (S.factors||[]).forEach(f=>e.z[f.id]=facZ(h,f.id));const add=(o,k,v)=>{o[k]=(o[k]||0)+v;};
 Object.entries(R.opt).forEach(([t,o])=>(e.opt[t]=e.opt[t]||[]).push({z:o.z,w:o.w}));
 E.sel.forEach(x=>add(e.sel,x.key,x.c*e.z[x.f]));E.pen.forEach(x=>add(e.pen,x.key,x.c*e.z[x.f]));E.dev.forEach(x=>add(e.dev,x.t,x.c*e.z[x.f]));
 E.plast.forEach(x=>add(e.plast,x.t,x.c*e.z[x.f]));E.epi.forEach(x=>add(e.epi,x.key,x.c*e.z[x.f]));E.opt.forEach(x=>(e.opt[x.t]=e.opt[x.t]||[]).push({z:x.a+x.b*e.z[x.f],w:x.w}));
 E.mut.forEach(x=>e.mut*=Math.exp(x.c*e.z[x.f]));
 /* 基因庫中為等位基因自訂的棲息地適配度（優先於演算結果）；深淵突變在沒有自訂的棲息地套用一般不利值 */
 S.loci.forEach(l=>l.alleles.forEach((a,k)=>{const key=l.sym+'^'+a.s;const v=a.hf&&a.hf[h.code];const cv=(e.sel[key]||0)+(l.abyss&&k>0&&+l.abyssW?+l.abyssW:0);if(cv)e.calc[key]=cv;if(v!==undefined&&v!==''&&v!==null&&isFinite(+v)){e.sel[key]=+v;}else if(l.abyss&&k>0&&+l.abyssW)add(e.sel,key,+l.abyssW);}));
 return e;}
function parseItem(t){const r={mut:{},newmut:{},pen:{},drive:{},shift:{},insert:[],self:false,litter:0,breeds:0};String(t||'').split('\n').forEach(line=>{line=line.replace(/#.*/,'').trim();if(!line)return;let m;
 if(m=line.match(/^mut\s+(\*|[A-Za-z0-9_]+)\s+[x×]?\s*([\d.]+)/i))r.mut[m[1]]=(r.mut[m[1]]||1)*+m[2];
 else if(m=line.match(/^newmut\s+([A-Za-z0-9_]+)\^(\S+)\s+(\S+)\s+([\d.]+)/i))((r.newmut[m[1]]=r.newmut[m[1]]||{})[m[2]]=r.newmut[m[1]][m[2]]||[]).push({to:m[3],r:+m[4]});
 else if(m=line.match(/^pen\s+([A-Za-z0-9_]+\^\S+)\s+([-+]?[\d.]+)/i))r.pen[m[1]]=(r.pen[m[1]]||0)+(+m[2]);
 else if(m=line.match(/^drive\s+([A-Za-z0-9_]+\^\S+)\s+([\d.]+)/i))r.drive[m[1]]=Math.min(1,Math.max(0,+m[2]));
 else if(m=line.match(/^shift\s+(\S+)\s+([-+]?[\d.]+)/i))r.shift[m[1]]=(r.shift[m[1]]||0)+(+m[2]);
 else if(m=line.match(/^insert\s+([A-Za-z0-9_]+)\^(\S+)\s+([\d.]+)/i))r.insert.push({sym:m[1],a:m[2],p:Math.min(1,+m[3])});
 else if(/^self\b/i.test(line))r.self=true;
 else if(m=line.match(/^litter\s+\+?(\d+)/i))r.litter+=+m[1];
 else if(m=line.match(/^breeds\s+\+?(\d+)/i))r.breeds+=+m[1];});return r;}
function combineItems_f0050(ids){const its=(S.items||[]).filter(it=>ids.includes(it.id));if(!its.length)return null;const o={mut:{},newmut:{},pen:{},drive:{},shift:{},insert:[],self:false,litter:0,names:its.map(i=>i.name)};
 its.forEach(it=>{const r=parseItem(it.rules);Object.entries(r.mut).forEach(([k,v])=>o.mut[k]=(o.mut[k]||1)*v);Object.entries(r.newmut).forEach(([s,m])=>Object.entries(m).forEach(([a,l])=>((o.newmut[s]=o.newmut[s]||{})[a]=(o.newmut[s][a]||[])).push(...l)));
  Object.entries(r.pen).forEach(([k,v])=>o.pen[k]=(o.pen[k]||0)+v);Object.assign(o.drive,r.drive);Object.entries(r.shift).forEach(([k,v])=>o.shift[k]=(o.shift[k]||0)+v);o.insert.push(...r.insert);if(r.self)o.self=true;o.litter+=r.litter;});return o;}
function combineItems(ids){const ok=(ids||[]).filter(id=>{const it=(S.items||[]).find(x=>x.id===id);return!it||itemOpen(it);});const o=combineItems_f0050.call(this,ok);if(o&&o.insert)o.insert=o.insert.filter(x=>alAvail(x.sym,x.a));return o;}
function uOf_f0050(ind,sym,basePen){if(ind.us!=null)return hashStr(ind.us+'|'+sym)/4294967296;if((ind.np||[]).includes(sym))return 0.9999;
 return hashStr((ind.id||'')+'|'+sym)/4294967296*Math.min(1,basePen)*0.999;}
function uOf(ind,sym,b){return uOf_f0050.call(this,ind,V78UK.get(sym)||sym,b);}
function normalizeG(ind){for(const l of S.loci){const sl=slots(l,ind.sex);const cur=ind.g[l.sym]||[null,null];ind.g[l.sym]=sl.map((on,i)=>on?(cur[i]!=null&&IDX.al[l.sym][cur[i]]?cur[i]:(cur[1-i]!=null&&IDX.al[l.sym][cur[1-i]]?cur[1-i]:l.alleles[0].s)):null);}}
function sugPriceNum(top){const m=S.meta;const lo=numOr(m.priceMin,1000),hi=numOr(m.priceMax,5000),st=Math.max(1,numOr(m.priceStep,50));const pctTop=Math.max(1e-6,top*100);
 const t=Math.min(1,Math.max(0,Math.log10(100/pctTop)/Math.log10(100/Math.max(1e-3,numOr(m.priceTopPct,0.1)))));return Math.round((lo+(hi-lo)*t)/st)*st;}
function sugPrice(r){return r.tier.price||fmtPrice(sugPriceNum(r.top));}
function rareGenes(ind,ex,hide){const v=variantInfo(ind).code;const thr=+S.meta.rareThr||0.1;const out=[];
 for(const l of S.loci){if(hide&&hide.has(l.sym))continue;const tot=locTot(l,v)||1;const wild=l.alleles[0]?.s;const ph=ex&&ex.loci[l.sym];
  for(const a of new Set(presOf(ind,l))){if(a===wild)continue;const o=IDX.al[l.sym][a];if(!o)continue;const q=freqFor(l,a,v)/tot;if(q>=thr)continue;
   const n=presOf(ind,l).filter(x=>x===a).length;let st;
   if(l.poly)st='數值';else if(ph&&ph.hidden)st='被遮蓋';else if(ph&&ph.exp.some(e=>e.s===a))st=(ph.np?'未外顯':'表現');else st='帶因';
   out.push({sym:l.sym,a,name:o.en||o.n,zh:o.n,q,st,hom:n>1});}}
 return out.sort((x,y)=>x.q-y.q);}
function rareCompact(list){const seen=new Set();return list.filter(x=>x.st==='表現'&&!seen.has(x.sym)&&seen.add(x.sym));}
function parseGen(g){const m=String(g||'').trim().toUpperCase().match(/^(?:N(\d+))?(?:F(\d+))?$/);return m&&(m[1]||m[2])?{n:+m[1]||0,f:+m[2]||0}:{n:0,f:0};}
function childLine(d,s){
 if(d.bg!==s.bg)return{bg:d.bg,donor:s.bg,gen:'N1'};/* 不同背景：歸入母本品系，父本品系為供體 */
 const gd=parseGen(d.gen),gs=parseGen(s.gen),dd=d.donor||'',sd=s.donor||'';
 if(!dd&&!sd)return{bg:d.bg,donor:'',gen:genStr(0,Math.max(gd.f,gs.f)+1)};/* 純品系內交 */
 if(dd&&!sd)return{bg:d.bg,donor:dd,gen:genStr(gd.n+1,0)};/* 帶供體 × 純背景＝回交 */
 if(sd&&!dd)return{bg:d.bg,donor:sd,gen:genStr(gs.n+1,0)};
 return{bg:d.bg,donor:dd,gen:genStr(Math.max(gd.n,gs.n),Math.max(gd.f,gs.f)+1)};}
function autoMarker(ind,hide){let best=null,bf=2;for(const l of S.loci){if(l.poly||(hide&&hide.has(l.sym)))continue;const wild=l.alleles[0]?.s;for(const a of presOf(ind,l)){if(a===wild)continue;const f=+(IDX.al[l.sym][a]?.f)||0;if(f<bf){bf=f;best=`${l.sym}^${a}`;}}}return best;}
function strain(ind,hide){const mk=ind.marker&&!(hide&&hide.has(String(ind.marker).split('^')[0]))?ind.marker:autoMarker(ind,hide);return`${ind.bg||S.meta.defaultBg}${ind.donor?'.'+ind.donor:''}${mk?'-'+mk:''}/${S.meta.lab}`;}
function genoStr(ind,hide){const xy=S.meta.sexSystem==='XY';const parts=[];
 for(const c of S.chromosomes){const locs=(IDX.groups[c.id]||[]).filter(l=>!(hide&&hide.has(l.sym)));const seg=[];
  for(const l of locs){const [a,b]=ind.g[l.sym]||[];const p=[a,b].filter(x=>x!=null);if(!p.length)continue;
   if(c.type==='MT')seg.push(`mt-${l.sym}^${p[0]}`);
   else if(c.type==='S2')seg.push(`${l.sym}^${p[0]}`);
   else if(p.length===1)seg.push(`${l.sym}^${p[0]}/${xy?'Y':'W'}`);
   else seg.push(`${l.sym}^${a}/${l.sym}^${b}`);}
  if(seg.length)parts.push((c.type==='S2'?(xy?'Y: ':'W: '):'')+seg.join(' '));}
 return parts.join(' ; ');}
function dateCode(iso){let s=String(iso||'').replace(/[^0-9]/g,'');if(s.length<8)s=todayISO().replace(/-/g,'');s=s.slice(0,8);return S.meta.idDateFmt==='YYYYMMDD'?s:s.slice(2);}
function lineCode(folderId,bg){return String(UI.idLine||bg||(typeof idCtxBg==='function'?idCtxBg():'')||S.meta.defaultBg||'NEW').toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,8)||'NEW';}
function nextId(folderId,bg){const code=lineCode(folderId,bg),dc=dateCode(UI.idDate),dg=+S.meta.idDigits||2;const ids=new Set(S.inds.map(i=>i.id));const pre=`${code}-${dc}-`;
 let n=+UI.idNum||0;if(!n){n=1;S.inds.forEach(i=>{if(i.id.startsWith(pre)){const k=parseInt(i.id.slice(pre.length),10);if(k>=n)n=k+1;}});}
 while(ids.has(pre+String(n).padStart(dg,'0')))n++;if(UI.idNum)UI.idNum=n+1;return pre+String(n).padStart(dg,'0');}
function colorName(hex){if(!isHex(hex))return'—';let [r,g,b]=h2r(hex).map(v=>v/255);const mx=Math.max(r,g,b),mn=Math.min(r,g,b),l=(mx+mn)/2,d=mx-mn;const s=d?(l>.5?d/(2-mx-mn):d/(mx+mn)):0;
 let h=0;if(d){h=mx===r?((g-b)/d+(g<b?6:0)):mx===g?((b-r)/d+2):((r-g)/d+4);h*=60;}
 if(l>.93&&s<.5)return'白';if(l<.12)return'黑';if(s<.12)return l>.75?'淺灰':l<.35?'深灰':'灰';
 const H6=[[12,'紅'],[35,'橙'],[52,'金黃'],[68,'檸檬黃'],[95,'黃綠'],[150,'綠'],[172,'青綠'],[192,'水青'],[212,'天藍'],[238,'藍'],[258,'靛藍'],[282,'紫'],[318,'洋紅'],[345,'玫瑰粉'],[361,'紅']];
 let n=H6.find(x=>h<x[0])[1];if(n==='紅'&&l>.7)n='粉紅';if(n==='橙'&&l>.72)n='杏色';if(n==='橙'&&l<.35)n='棕';if((n==='金黃'||n==='檸檬黃')&&l>.85)n='奶油黃';
 const pre=l>.82?'淡':l>.68?'淺':l<.3?'深':s<.3?'灰':'';return pre+n;}
function profile(ind){const ex=express(ind,ind.hab,false);const tn=tradeName(ind,ex);const r=rarity(ind);return{ex,tn,r};}
function cardCfg(){const m=S.meta;if(!m.card||typeof m.card!=='object')m.card={};const c=m.card;if(!c.f)c.f={...CARD_DEF,colors:m.dcColors?1:0};Object.keys(CARD_DEF).forEach(k=>{if(c.f[k]==null)c.f[k]=CARD_DEF[k];});
 if(!c.v2){c.f.poly=0;c.v2=1;}if(!c.v4){c.f.desc=1;if(c.pf){c.pf.desc=1;c.pf.parents=1;}c.v4=1;}if(!c.v5){c.f.acc=1;if(c.pf)c.pf.acc=1;c.v5=1;}if(!c.pf)c.pf={...POST_DEF,rarest:m.postRarest===false?0:1};Object.keys(POST_DEF).forEach(k=>{if(c.pf[k]==null)c.pf[k]=POST_DEF[k];});
 if(!c.v3){c.f.breeds=1;c.f.rare=1;c.pf.breeds=1;c.pf.rare=1;c.v3=1;}
 if(!Array.isArray(c.hideLoci))c.hideLoci=[];if(!c.fx||typeof c.fx!=='object')c.fx={...c.f,het:1,masked:1};Object.keys(CARD_DEF).forEach(k=>{if(c.fx[k]==null)c.fx[k]=CARD_DEF[k];});if(!Array.isArray(c.presets))c.presets=[];if(!Array.isArray(c.hidePoly))c.hidePoly=S.poly.some(p=>p.id==='TL')?['TL']:[];return c;}
