function parseCol(t){const o={};String(t||'').split(/[;,\n]/).forEach(p=>{const m=p.split('=');if(m.length!==2)return;const k=m[0].trim();let v=m[1].trim();if(v&&v[0]!=='#')v='#'+v;if(k&&isHex(v))o[k]=v.toLowerCase();});return o;}
function mixHex(list){const rs=list.map(h2r);return r2h([0,1,2].map(i=>rs.reduce((t,r)=>t+r[i],0)/rs.length));}
function jitterHex(h){let [r,g,b]=h2r(h).map(v=>v/255);const mx=Math.max(r,g,b),mn=Math.min(r,g,b);let hh=0,s=0,l=(mx+mn)/2;const d=mx-mn;
 if(d){s=l>.5?d/(2-mx-mn):d/(mx+mn);hh=mx===r?((g-b)/d+(g<b?6:0)):mx===g?((b-r)/d+2):((r-g)/d+4);hh/=6;}
 hh=(hh+(rnd()-.5)*0.035+1)%1;s=Math.max(0,Math.min(1,s+(rnd()-.5)*0.12));l=Math.max(0.03,Math.min(.97,l+(rnd()-.5)*0.08));
 const q=l<.5?l*(1+s):l+s-l*s,p=2*l-q;const f=t=>{t=(t+1)%1;return t<1/6?p+(q-p)*6*t:t<.5?q:t<2/3?p+(q-p)*(2/3-t)*6:p;};
 return r2h([f(hh+1/3),f(hh),f(hh-1/3)].map(v=>v*255));}
function blendHex(base,top,mode,opa){const a=h2r(base).map(v=>v/255),b=h2r(top).map(v=>v/255);let r;
 if(mode==='color'){const [h,s]=hex2hsl(top);const [,,l]=hex2hsl(base);r=h2r(hsl2hex(h,s,l)).map(v=>v/255);}
 else r=a.map((x,i)=>{const y=b[i];switch(mode){case'multiply':return x*y;case'screen':return 1-(1-x)*(1-y);case'overlay':return x<.5?2*x*y:1-2*(1-x)*(1-y);
  case'soft':return(1-2*y)*x*x+2*y*x;case'add':return Math.min(1,x+y);case'lighten':return Math.max(x,y);case'darken':return Math.min(x,y);default:return y;}});
 const o=Math.max(0,Math.min(1,opa==null||opa===''?1:+opa));return r2h(a.map((x,i)=>(x+(r[i]-x)*o)*255));}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已複製');}catch(e){const ta=document.getElementById('io-out');if(ta){ta.value=text;ta.focus();ta.select();toast('請按 Ctrl/⌘+C 複製選取的文字');}else toast('無法自動複製');}}
