function habSpJSON(sp){const o=JSON.parse(JSON.stringify(sp));const L=habsOf(sp);o.habitats=clone(L);const R=sp.room&&typeof sp.room==='object'?sp.room:null;if(R){o.room=o.room||{};const hc={};L.forEach(h=>{const v=R.hab[h.code];if(v)hc[h.code]=clone(v);});Object.keys(R.habOwn||{}).forEach(k=>{hc[k]=clone(R.habOwn[k]);});o.room.hab=hc;delete o.room.pos;delete o.room.habOwn;}delete o.habUse;return o;}
