function setCloud(msg,err){CLOUD.msg=msg||'';CLOUD.err=err||'';document.querySelectorAll('.cloudstat').forEach(e=>{e.textContent=cloudLine();e.style.color=CLOUD.err||CLOUD.conflict?'var(--danger)':'';});
 try{if(err)saveNote('cloudErr',err);else if(CLOUD.conflict)saveNote('cloudErr','雲端有其他裝置的較新修改，請到「公開與同步」處理');else if(/^已同步|^已是最新/.test(msg||''))saveNote('cloud');}catch(e){}}
function cloudLine(){if(CLOUD.mode==='local')return'雲端同步未啟用：資料只存在這個瀏覽器（需要在 Claude 中開啟此頁）。';if(CLOUD.mode==='boot')return'正在連線雲端…';
 if(CLOUD.conflict)return'另一個裝置剛更新了雲端資料，這裡暫停同步。請到「公開與同步」選擇要保留哪一邊。';return(CLOUD.err||CLOUD.msg||'已連線雲端')+(CLOUD.lastAt?`（最後同步 ${CLOUD.lastAt.toLocaleTimeString()}）`:'');}
function scheduleSync(){if(CLOUD.mode!=='owner'||CLOUD.conflict)return;if(CLOUD.loading||CLOUD.blocked||DATA_NEWER)return;clearTimeout(CLOUD.timer);CLOUD.timer=setTimeout(()=>cloudSync(),1500);setCloud('有未同步的修改…');}
async function runOps(ops,label){let done=0;const q=ops.slice();const worker=async()=>{while(q.length){const op=q.shift();
  if(op[0]==='set'){await dbTry(()=>CLOUD.db.doc(op[1]).set(op[2]));CLOUD.last.set(op[1],op[3]);}else{await dbTry(()=>CLOUD.db.doc(op[1]).delete());CLOUD.last.delete(op[1]);}
  done++;if(ops.length>8&&done%5===0)setCloud(`${label} ${done}/${ops.length}…`);}};
 await Promise.all([worker(),worker(),worker(),worker()]);}
async function cloudSync(){if(CLOUD.mode!=='owner'||CLOUD.conflict)return;if(CLOUD.loading||CLOUD.blocked||DATA_NEWER)return;if(CLOUD.busy){CLOUD.dirty=true;return;}CLOUD.busy=true;CLOUD.dirty=false;clearTimeout(CLOUD.timer);
 try{setCloud('同步中…');const st=await dbTry(()=>CLOUD.db.doc('priv/store').get());const remote=st.exists?st.data():null;
  if(remote&&remote.rev&&CLOUD.rev&&remote.rev!==CLOUD.rev){CLOUD.conflict=true;setCloud();if(UI.tab==='pub')renderPubCfg();return;}
  if(remote&&remote.rev&&!CLOUD.rev&&!CLOUD.firstSync){CLOUD.blocked=true;setCloud('','雲端已有資料，但這個頁面還沒讀取過；為避免覆蓋，已暫停同步。請重新整理頁面。');return;}
  if(remote&&+remote.schema>APP_SCHEMA){DATA_NEWER=+remote.schema;setCloud('',newerMsg());return;}
  const priv=privDocs();const {m:pub,built,on}=pubDocs();const want=new Map([...priv,...pub]);const ops=[];
  want.forEach((o,p)=>{if(p==='priv/store')return;const j=stable(o);if(CLOUD.last.get(p)!==j)ops.push(['set',p,o,j]);});
  CLOUD.last.forEach((j,p)=>{if(want.has(p)||p==='priv/store'||p==='pub/site')return;const mm=p.match(/^pub\/(sp_[^/]+)/);if(p.startsWith('priv/')||!mm||built.has(mm[1])||!on.has(mm[1]))ops.push(['del',p]);});
  if(ops.length)await runOps(ops,'同步中');
  if(ops.length||!remote||CLOUD.forceStore){CLOUD.forceStore=false;const rev=Math.random().toString(36).slice(2,10);await dbTry(()=>CLOUD.db.doc('priv/store').set({...priv.get('priv/store'),rev,updatedAt:new Date().toISOString()}));CLOUD.rev=rev;}
  CLOUD.lastAt=new Date();setCloud(ops.length?`已同步 ${ops.length} 筆變更`:'已是最新');}
 catch(e){setCloud('',`同步失敗：${e&&e.code==='quota_exceeded'?'雲端空間已滿（'+(e.message||'')+'）':e&&e.code==='invalid_argument'?'資料格式或大小超出限制（單筆上限 256KB）':(e&&e.message)||'未知錯誤'}。修改仍保存在這個瀏覽器，下次修改時會再試。`);}
 finally{CLOUD.busy=false;if(UI.tab==='pub')renderPubCfg();if(CLOUD.dirty&&!CLOUD.conflict)scheduleSync();}}
async function cloudLoadPriv(){
 /* 原始定義 */
 let res=await (async ()=>{const db=CLOUD.db;const st=await dbTry(()=>db.doc('priv/store').get());if(!st.exists)return null;const s=st.data();CLOUD.last.clear();const species=[];for(const key of s.keys||[]){const k='sp_'+encSeg(key);const c=await dbTry(()=>db.doc('priv/'+k).get());if(!c.exists)continue;const raw=c.data();CLOUD.last.set('priv/'+k,stable(raw));const cfg=clone(raw);const order=cfg.order||[];delete cfg.order;
  const docs=await getAll(`priv/${k}/inds`);docs.forEach(d=>CLOUD.last.set(d.path,stable(d.data)));const byId=new Map(docs.map(d=>[d.data.id,clone(d.data)]));
  cfg.inds=[...order.map(id=>byId.get(id)).filter(Boolean),...[...byId.values()].filter(x=>!order.includes(x.id))];species.push(cfg);}const site=await dbTry(()=>db.doc('pub/site').get());if(site.exists){CLOUD.last.set('pub/site',stable(site.data()));
  for(const e of site.data().species||[]){const d=await dbTry(()=>db.doc('pub/'+e.seg).get());if(d.exists)CLOUD.last.set('pub/'+e.seg,stable(d.data()));(await getAll(`pub/${e.seg}/inds`)).forEach(x=>CLOUD.last.set(x.path,stable(x.data)));(await getAll(`pub/${e.seg}/room`)).forEach(x=>CLOUD.last.set(x.path,stable(x.data)));}}CLOUD.rev=s.rev||null;const ext=await cloudLoadExt(db);return{v:2,schema:+s.schema||2,cur:s.cur,species,...ext};})();
 /* f0690：後處理 */
 try{if(res&&CLOUD.db)(await getAll('pub/own/keys')).forEach(d=>CLOUD.last.set(d.path,stable(d.data)));}catch(e){}
 /* 最後一版：後處理 */
 try{const st=CLOUD.last.get('pub/site');const site=st?JSON.parse(st):null;for(const p of [...((site&&site.showDocs)||[]),...((site&&site.verDocs)||[])]){const d=await CLOUD.db.doc(p).get();if(d.exists)CLOUD.last.set(p,stable(d.data()));}}catch(e){}
 return res;}
async function cloudPull(){setCloud('從雲端載入中…');try{const r=await cloudLoadPriv();if(r&&r.species.length){STORE=wrapStore(r);useSpecies(STORE.cur);saveLocal();CLOUD.conflict=false;hdr();show(UI.tab);setCloud('已載入雲端資料');}else setCloud('雲端還沒有資料');}catch(e){setCloud('',`無法從雲端載入：${(e&&e.message)||e}`);}}
async function cloudPushOverwrite(){CLOUD.conflict=false;const st=await CLOUD.db.doc('priv/store').get();CLOUD.rev=st.exists?st.data().rev:null;await cloudSync();}
function renderPubCfg(){renderPubCfgPanels();
 try{tpvSample();hwpKick();tpvKick();}catch(e){}
 try{const on=document.querySelector('#tab-pub [data-pub="on"]');const p=on&&on.closest('.panel');if(p&&!document.querySelector('#tab-pub .evpanel'))p.insertAdjacentHTML('afterend',evPanel());}catch(e){console.error(e);}}
