function locTile(l,i){const fl=LOC_FLAGS.filter(([k])=>k==='leth'?l.alleles.some(a=>a.leth):!!l[k]).map(f=>f[1]);const on=UI.openLoc===i;
 return`<button class="cc gt loct${on?' on':''}" type="button" data-act="locOpen" data-i="${i}" aria-expanded="${on}"><span class="ccimg gt-img gt-code"><b class="gt-cd">${H(l.sym)}</b></span><span class="ccb"><b class="gt-n">${H(l.name)}${newB(l)}</b><span class="gt-en${fl.includes('機密')?'" style="color:var(--danger)':''}">${H(fl.join('·')||(l.poly?'多基因 '+l.poly:MODES[l.mode]||`${l.alleles.length} 個等位`))}</span></span></button>`;}
function cropInk(c){const x=c.getContext('2d');const tx=x.getImageData(0,0,c.width,c.height).data;let x1=c.width,y1=c.height,x2=0,y2=0;for(let yy=0;yy<c.height;yy+=2)for(let xx=0;xx<c.width;xx+=2){if(tx[(yy*c.width+xx)*4+3]>20){if(xx<x1)x1=xx;if(xx>x2)x2=xx;if(yy<y1)y1=yy;if(yy>y2)y2=yy;}}
 if(x2<=x1||y2<=y1)return c;const out=document.createElement('canvas');out.width=x2-x1+4;out.height=y2-y1+4;out.getContext('2d').drawImage(c,x1-2,y1-2,out.width,out.height,0,0,out.width,out.height);return out;}
function decorProc(img,o){const m=o.mode;if(!PROC_EX.has(m))return decorMask(decorDensity(img,o),o);
 const iw=img.naturalWidth||img.width,ih=img.naturalHeight||img.height;const k=Math.min(1,(m==='original'||m==='recolor'?1200:760)/Math.max(iw,ih));const w=Math.max(8,Math.round(iw*k)),h=Math.max(8,Math.round(ih*k));
 const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(img,0,0,w,h);const id=x.getImageData(0,0,w,h);const px=id.data;
 let br=0,bg=0,bb=0,n=0;const P=Math.max(2,Math.round(Math.min(w,h)*.03));[[0,0],[w-P,0],[0,h-P],[w-P,h-P]].forEach(([sx,sy])=>{for(let yy=sy;yy<sy+P;yy++)for(let xx=sx;xx<sx+P;xx++){const i=(yy*w+xx)*4;br+=px[i];bg+=px[i+1];bb+=px[i+2];n++;}});br/=n;bg/=n;bb/=n;
 const al=new Float32Array(w*h),d=new Float32Array(w*h);const con=Math.max(.3,+o.con||1);
 for(let i=0;i<w*h;i++){const r=px[i*4],g=px[i*4+1],b=px[i*4+2];let a=px[i*4+3]/255;if(o.bg==='auto'){const dist=Math.hypot(r-br,g-bg,b-bb)/441;a*=Math.min(1,Math.max(0,(dist-.07)/.1));}
  const lum=(.299*r+.587*g+.114*b)/255;const v=Math.max(0,((o.inv?lum:1-lum)-.1)/.9);al[i]=a;d[i]=Math.min(1,Math.pow(v,1/con))*a;}
 if(m==='original'){for(let i=0;i<w*h;i++)px[i*4+3]=Math.round(al[i]*255);x.putImageData(id,0,0);return cropInk(c);}
 if(m==='recolor'){const lw=Math.max(0,+o.lineW||0)*Math.max(w,h)/600;const pad=Math.ceil(lw)+4;const mc=document.createElement('canvas');mc.width=w;mc.height=h;const mx=mc.getContext('2d');const mi=mx.createImageData(w,h);
  for(let i=0;i<w*h;i++){mi.data[i*4]=mi.data[i*4+1]=mi.data[i*4+2]=255;mi.data[i*4+3]=al[i]>.45?255:Math.round(Math.max(0,(al[i]-.25)*4)*255);}mx.putImageData(mi,0,0);
  const out=document.createElement('canvas');out.width=w+pad*2;out.height=h+pad*2;const ox=out.getContext('2d');if(lw>0){const lc=decorTint(mc,o.lineC||'#2459f0');for(let a=0;a<24;a++){const t=a/24*Math.PI*2;ox.drawImage(lc,pad+Math.cos(t)*lw,pad+Math.sin(t)*lw);}}
  ox.drawImage(decorTint(mc,o.fillC||'#ffffff'),pad,pad);return cropInk(out);}
 const cs=Math.max(3,Math.min(16,+o.den||7));const sc=1.6;const out=document.createElement('canvas');out.width=Math.round(w*sc);out.height=Math.round(h*sc);const ox=out.getContext('2d');
 const cells=[];let cx1=1e9,cx2=-1;for(let y0=0;y0<h;y0+=cs)for(let x0=0;x0<w;x0+=cs){let A=0,V=0,R=0,G=0,B=0,nn=0;for(let yy=y0;yy<Math.min(h,y0+cs);yy++)for(let xx=x0;xx<Math.min(w,x0+cs);xx++){const i=yy*w+xx;A+=al[i];V+=d[i];R+=px[i*4]*al[i];G+=px[i*4+1]*al[i];B+=px[i*4+2]*al[i];nn++;}
  if(!nn)continue;const cell={x0,y0,A:A/nn,V:V/nn,r:A?R/A:0,g:A?G/A:0,b:A?B/A:0};cells.push(cell);if(cell.A>.3){cx1=Math.min(cx1,x0);cx2=Math.max(cx2,x0+cs);}}
 const split=(cx1+cx2)/2;const ramp='.,:-_=+|/\\[]{}<>o0O8#';ox.textAlign='center';ox.textBaseline='middle';ox.font=`700 ${cs*sc*1.2}px "Space Mono",ui-monospace,Menlo,monospace`;
 cells.forEach(c2=>{if(c2.A<.3)return;const X=c2.x0*sc,Y=c2.y0*sc,S2=cs*sc;const asc=m==='ascii'||(m==='mix'&&c2.x0+cs/2>split);
  if(asc){if(c2.V<.06)return;ox.fillStyle='#fff';ox.fillText(ramp[Math.min(ramp.length-1,Math.floor(c2.V*ramp.length))],X+S2/2,Y+S2/2);}
  else if(m==='mosaicC'){ox.fillStyle=`rgb(${Math.round(c2.r)},${Math.round(c2.g)},${Math.round(c2.b)})`;ox.fillRect(X,Y,S2+.5,S2+.5);}
  else{ox.fillStyle=`rgba(255,255,255,${Math.min(1,.22+c2.V*.95).toFixed(3)})`;ox.fillRect(X,Y,S2+.5,S2+.5);}});
 return cropInk(out);}
function decorDrawEx2(x,e,i,W,H,S1){let bw=S1,bh=S1;
 if(e.t==='check'){x.lineWidth=Math.max(1.2,S1*.09);x.strokeRect(-S1/2,-S1/2,S1,S1);if(e.on){x.lineWidth=Math.max(1.5,S1*.15);x.lineCap='round';x.lineJoin='round';x.beginPath();x.moveTo(-S1*.28,0);x.lineTo(-S1*.06,S1*.24);x.lineTo(S1*.34,-S1*.3);x.stroke();}}
 else if(e.t==='progress'){bw=Math.max(10,(+e.w||.6)*W);bh=Math.max(2,S1);x.lineWidth=Math.max(1,H*.0025);x.strokeRect(-bw/2,-bh/2,bw,bh);const v=Math.max(0,Math.min(1,+e.v||0));x.fillRect(-bw/2,-bh/2,bw*v,bh);
  x.font=`700 ${Math.max(8,bh*1.1)}px ${delFont('mono')}`;x.textAlign='right';x.textBaseline='bottom';x.fillText(Math.round(v*100)+'%',bw/2,-bh/2-bh*.3);}
 else if(e.t==='rect'){bw=Math.max(4,(+e.w||.25)*W);bh=S1;if(e.fill)x.fillRect(-bw/2,-bh/2,bw,bh);else{x.lineWidth=Math.max(1,H*.003*(+e.lw||1));x.strokeRect(-bw/2,-bh/2,bw,bh);}}
 else if(e.t==='xmark'){x.lineWidth=Math.max(1.2,S1*.14);x.beginPath();x.moveTo(-S1/2,-S1/2);x.lineTo(S1/2,S1/2);x.moveTo(S1/2,-S1/2);x.lineTo(-S1/2,S1/2);x.stroke();}
 else if(e.t==='ring'){x.lineWidth=Math.max(1,H*.0035);x.setLineDash([S1*.03,S1*.022]);x.beginPath();x.arc(0,0,S1/2,0,6.2832);x.stroke();x.setLineDash([]);x.lineWidth=Math.max(.6,H*.0015);x.beginPath();x.arc(0,0,S1*.44,0,6.2832);x.stroke();
  const q=S1*.07;x.lineWidth=Math.max(1,H*.004);x.beginPath();[[0,-1],[1,0],[0,1],[-1,0]].forEach(([a,b])=>{x.moveTo(a*S1*.5,b*S1*.5);x.lineTo(a*(S1*.5+q),b*(S1*.5+q));});x.stroke();}
 else return null;return{bw,bh};}
function fxOpts(e,o){if(!e.fx)return null;if(e.fx==='main')return{mode:o.mode||'halftone',den:o.den,bg:o.bg||'auto',inv:!!o.inv,con:o.con||1,fillC:o.fillC,lineC:o.lineC,lineW:o.lineW,seed:o.seed||1};
 return{mode:e.fx,den:7,bg:'auto',inv:false,con:1,fillC:'#ffffff',lineC:'#2459f0',lineW:6,seed:1,...(e.fxp||{})};}
function dobjFx(im,e,o){const p=fxOpts(e,o);if(!p)return im;const k=(im.src||'')+'|'+JSON.stringify(p);if(!DOBJ_FX.has(k)){let r=im;try{r=decorProc(im,p);}catch(err){}DOBJ_FX.set(k,r);if(DOBJ_FX.size>40)DOBJ_FX.delete(DOBJ_FX.keys().next().value);}return DOBJ_FX.get(k);}
function delSet(e,k,v){if(k.includes('.')){const [a,b]=k.split('.');e[a]=e[a]&&typeof e[a]==='object'?e[a]:{};e[a][b]=v;}else e[k]=v;}
function dcCtxEx(e,i){const rng=(k,min,max,step,v,lab)=>`<label class="f st-rng">${lab}<input type="range" min="${min}" max="${max}" step="${step}" data-del="${i}|${k}" value="${H(v)}"></label>`;const ck=(k,v,lab,tip)=>`<label class="tiny st-chk"${tip?` title="${H(tip)}"`:''}><input type="checkbox" data-del="${i}|${k}"${v?' checked':''}>${lab}</label>`;
 if(e.t==='text')return ck('outline',e.outline,'只描邊');
 if(e.t==='check')return ck('on',e.on,'已勾選');
 if(e.t==='progress')return rng('v',0,1,.01,e.v==null?.6:e.v,'進度');
 if(e.t==='rect')return ck('fill',e.fill,'填滿');
 if(e.t!=='img')return'';const p=e.fxp||{};const own=e.fx&&e.fx!=='main';
 return`<label class="f" title="和${TERMS.mainImg}一樣的後處理；「和${TERMS.mainImg}相同」會沿用${TERMS.mainImg}目前的${TERMS.fx}與參數">${TERMS.fx}<select data-del="${i}|fx"><option value="">原圖（不處理）</option><option value="main"${e.fx==='main'?' selected':''}>和${TERMS.mainImg}相同（同參數）</option>${Object.entries(DECOR_MODES).filter(([k])=>k!=='original').map(([k,n])=>`<option value="${k}"${e.fx===k?' selected':''}>${H(n)}</option>`).join('')}</select></label>
  ${own?rng('fxp.den',3,16,1,p.den||7,'密度')+rng('fxp.con',.5,2.5,.1,p.con||1,'對比')+`<label class="f">去背<select data-del="${i}|fxp.bg"><option value="auto"${(p.bg||'auto')==='auto'?' selected':''}>自動</option><option value="none"${p.bg==='none'?' selected':''}>不去背</option></select></label>`+ck('fxp.inv',p.inv,'明暗反轉'):''}
  ${own&&e.fx==='recolor'?`<label class="f">填色<input type="color" data-del="${i}|fxp.fillC" value="${H(p.fillC||'#ffffff')}"></label><label class="f">外框色<input type="color" data-del="${i}|fxp.lineC" value="${H(p.lineC||'#2459f0')}"></label>${rng('fxp.lineW',0,20,1,p.lineW==null?6:p.lineW,'外框粗細')}`:''}`;}
