 const head=isPost?[`${post+1}. ${idS}`,f.nick&&ind.nick?ind.nick:'',f.sex?sexSym(ind.sex):''].filter(Boolean).join(' '):[f.id?`【${idS}】`:'',f.nick&&ind.nick?ind.nick:'',f.sex?sexSym(ind.sex):''].filter(Boolean).join(' ');
 const head2=[f.variant?taxLabel(ind):'',f.tier?`${r.tier.en} ${r.tier.zh}${isPost?'':`（前 ${pct(r.top)}）`}`:'',f.price&&!isPost?indPrice(ind,r):''].filter(Boolean).join(' · ');
