 o.rows.filter(x=>x.k!=='strain'&&x.k!=='gen').forEach(x=>String(x.md).split('\n').forEach(l=>L.push(l)));
 if(isPost)L.push([f.price&&PRICE_ST.has(ind.status)?`價格 ${indPrice(ind,r)||'洽詢'}`:'',(STATUS[ind.status]||'').replace(/（.*）/,''),ind.rights?'育種權 '+ind.rights:''].filter(Boolean).join(' · '));
