function artModes(kind){return kind==='ind'?{hero:`跟隨主視覺${TERMS.mainImg}的效果`,...DECOR_MODES}:{cutout:'去背全彩（自動裁切）',solid:SIL_MODES.solid,ink:SIL_MODES.ink,photo:SIL_MODES.photo,...DECOR_MODES};}
function artProc(im,mode,p){p={...ART_PARAM_DEF,...(p||{})};if(mode==='solid'||mode==='ink')return{cv:silCanvas(im,mode),raw:false};
 const o={mode,den:+p.den||7,bg:'auto',inv:false,con:+p.con||1,fillC:p.fillC,lineC:p.lineC,lineW:+p.lineW,seed:1};return{cv:decorProc(im,o),raw:RAW_MODES.has(mode)};}
function artCanvas(cv,max){const k=Math.min(1,(max||600)/Math.max(cv.width,cv.height));const o=document.createElement('canvas');o.width=Math.max(1,Math.round(cv.width*k));o.height=Math.max(1,Math.round(cv.height*k));o.getContext('2d').drawImage(cv,0,0,o.width,o.height);return o;}
