function cardArtCfg(sp){sp=sp||S;const m=sp.meta;if(!m.cardArt||typeof m.cardArt!=='object')m.cardArt={};const a=m.cardArt;Object.keys(CARDART_DEF).forEach(k=>{if(a[k]===undefined)a[k]=clone(CARDART_DEF[k]);});if(!a.cache||typeof a.cache!=='object')a.cache={};return a;}
