 const seen=new Set();const names=ord.map(s=>{let v=String(A(s).n||s).replace(/[|=&\n]/g,' ').trim()||s;if(seen.has(v))v+=' '+s;seen.add(v);return v;});
 const bands=ord.map((s,i)=>({s,zh:names[i],en:String(A(s).en||'').replace(/[|\n]/g,' ').trim(),col:cols[i],max:i<n-1?cut[i]:999,f0:cls[s],f1:(i<n-1?F(cut[i]):1)-(i?F(cut[i-1]):0)}));
