  if(cs.length!==segs.length){add(w,str,'需要手動修改（條件格式無法辨識）','check');return;}const m=cs.map(mapC);const k=m.some(x=>x.k==='check')?'check':m.some(x=>x.k==='warn')?'warn':'auto';
