 texts.forEach(([w,get,set])=>{const ls=String(get()||'').split('\n');let ch=false;const out=ls.map(l=>{const code=l.replace(/#.*/,'');if(!re.test(code))return l;add(w,l.trim(),'# 〔轉換停用〕'+l.trim(),'off');ch=true;return'# 〔轉換停用〕'+l;});if(apply&&ch)set(out.join('\n'));});
