function lookBoxes(T){const out={};const put=(k,x,y,w,h)=>{if(!k||!(w>0)||!(h>0))return;const b=out[k];if(!b){out[k]={x,y,w,h};return;}const x2=Math.max(b.x+b.w,x+w),y2=Math.max(b.y+b.h,y+h);b.x=Math.min(b.x,x);b.y=Math.min(b.y,y);b.w=x2-b.x;b.h=y2-b.y;};
 if(Array.isArray(T.parts)){T.parts.forEach(p=>put(p.k,p.x,p.y,p.w,p.h));return out;}
 if(T.flat&&Array.isArray(T.flat.parts)&&T.flat.parts.length){T.flat.parts.forEach(p=>put(p.k,p.x,p.y,p.w,p.h));return out;}
 const eff=lookEff(T);(T.layers||[]).forEach(l=>{if(l.hid)return;const pt=lookPart(eff.get(l));if(pt)put(pt.key,l.x,l.y,l.w,l.h);});return out;}
function accNameHit(nm,name){nm=String(nm||'');name=String(name||'').trim();if(!name)return false;let i=nm.indexOf(name);while(i>=0){const c=nm.charAt(i+name.length);if(!c||!/[0-9A-Za-z]/.test(c))return true;i=nm.indexOf(name,i+1);}return false;}
function accAutoRows(rows,a,pose){const p=pose?lookPose(pose):null;const tn=new Set(p?(p.layers||[]).filter(l=>!lookPart(l.pt)).map(l=>lookNorm(l.n)):[]);
 const own=r=>!!a&&(accNameHit(r.name,a.name)||accNameHit(r.name,a.id));const others=(typeof STORE!=='undefined'&&STORE.acc||[]).filter(x=>x&&a&&x.id!==a.id);
 const accish=r=>{const nm=String(r.name||'');return ACC_RE.test(nm)||others.some(x=>accNameHit(nm,x.name)||accNameHit(nm,x.id))||(r.k==='l'&&tn.has(lookNorm(nm)));};
 const mine=rows.some(r=>r.k!=='a'&&own(r));
 const eff=i=>{let r=rows[i];while(r){if(r.pt)return r.pt;r=r.parent>=0?rows[r.parent]:null;}return'';};
 /* 群組已經是飾品（或不使用）時，裡面的圖層跟著群組，不另外標，這樣在對應表改群組就整組一起改 */
 rows.forEach(r=>{if(r.k==='a')return;const up=r.parent>=0?eff(r.parent):'';if(up===ACC_PT||up===ACC_NO){/* 第 168 版：群組裡的圖層名稱只是剛好對到部位（例如 Photoshop 的「從選取範圍」被學成遠翅的別名）時也跟著群組；要指定部位請寫 @部位 */if(r.pt&&r.pt===r.auto&&!/@/.test(r.name)){r.pt='';r.auto='';}return;}if(own(r)){r.pt=ACC_PT;r.auto=ACC_PT;}else if(accish(r)){r.pt=mine?ACC_NO:ACC_PT;r.auto=r.pt;}});rows.forEach((r,i)=>{if(r.k==='l'&&!eff(i)){r.pt=mine?ACC_NO:ACC_PT;r.auto=r.pt;}});
 if(mine)return[];
 /* 最上層的飾品群組或圖層看起來是不同件（編號不同的「飾品1」「飾品2」，或是其他飾品的名稱）：不知道哪一組是這件。
    同一件分成「飾 後帶」「飾品 冠」幾組的照舊全部匯入 */
 const top=rows.filter(r=>r.k!=='a'&&r.pt===ACC_PT&&!(r.parent>=0&&eff(r.parent)===ACC_PT));const num=r=>{const m=String(r.name||'').match(/(?:飾品|配件|acc(?:essory)?)\s*[_-]?\s*(\d+)/i);return m?m[1]:null;};
 const diff=new Set(top.map(num).filter(Boolean)).size>1||top.some(r=>others.some(x=>accNameHit(r.name,x.name)||accNameHit(r.name,x.id)));return top.length>1&&diff?top.map(r=>r.name):[];}
