function lookGeneOK(l,ind){if(!ind||!l||!l.g)return true;const cs=parseConds(l.g);if(!cs.length)return true;try{return cs.every(c=>condMet(c,ind));}catch(e){return true;}}
function rgLegend(cv){const w=cv.width,h=cv.height;let d;try{d=cv.getContext('2d').getImageData(0,0,w,h).data;}catch(e){return[];}const cnt=new Map();let op=0;
 for(let i=0;i<d.length;i+=4){if(d[i+3]<200)continue;op++;const k=(d[i]<<16)|(d[i+1]<<8)|d[i+2];cnt.set(k,(cnt.get(k)||0)+1);}
 const min=Math.max(20,op*0.002);const rm=looksCfg().regionMap||{};
 return[...cnt.entries()].filter(([,n])=>n>=min).sort((a,b)=>b[1]-a[1]).slice(0,16).map(([k,n])=>{const c='#'+k.toString(16).padStart(6,'0');const pk=rm[c]&&palSlots().some(s=>s.k===rm[c])?rm[c]:((palSlots().find(s=>String(s.base||'').toLowerCase()===c)||{}).k||'');return{c,n,pk};});}
function rgMasks(cv,leg){const w=cv.width,h=cv.height;const d=cv.getContext('2d').getImageData(0,0,w,h).data;const cols=leg.map(e=>h2r(e.c));const outs=leg.map(()=>new ImageData(w,h));
 for(let i=0;i<d.length;i+=4){const a=d[i+3];if(!a)continue;let best=0,bd=1e12;for(let j=0;j<cols.length;j++){const c=cols[j];const q=(d[i]-c[0])**2+(d[i+1]-c[1])**2+(d[i+2]-c[2])**2;if(q<bd){bd=q;best=j;}}const o=outs[best].data;o[i]=o[i+1]=o[i+2]=255;o[i+3]=a;}
 return outs.map(im=>{const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').putImageData(im,0,0);return c;});}
function lookExpandRegions(leaves){const out=[];const L=looksCfg();L.regionMap=L.regionMap&&typeof L.regionMap==='object'?L.regionMap:{};
 for(const [r,ri] of leaves){if(r.k!=='l'||r.role!=='region'||!r.ly||!r.ly.canvas){out.push([r,ri]);continue;}const leg=(rgLeg(r)||[]).filter(e=>e.pk);if(!leg.length)continue;
  leg.forEach(e=>{L.regionMap[e.c]=e.pk;});const all=rgLeg(r);const masks=rgMasks(r.ly.canvas,all);const by=new Map();
  all.forEach((e,j)=>{if(!e.pk)return;const m=masks[j];if(!by.has(e.pk))by.set(e.pk,m);else by.get(e.pk).getContext('2d').drawImage(m,0,0);});
  [...by.entries()].forEach(([pk,cv],j)=>{const ly=Object.assign({},r.ly,{canvas:cv});out.push([Object.assign({},r,{role:'fill',pk,name:`${r.name} 色:${pk}`,ly,i:r.i+(j+1)/100}),ri]);});}
 return out;}
