function guTabName(t){const b=document.querySelector&&document.querySelector(`#tabs button[data-tab="${t}"]`);return(b&&b.textContent.trim())||t||'';}
function guLabel(a,b){const ch=[];if(a&&b&&a.spk===b.spk){GU_CNT.forEach(([k,n])=>{if(a[k]!==b[k])ch.push(`${n} ${a[k]}→${b[k]}`);});}if(a&&b){if(a.acc!==b.acc)ch.push(`飾品 ${a.acc}→${b.acc}`);if(a.sp!==b.sp)ch.push(`物種 ${a.sp}→${b.sp}`);if(a.own!==b.own)ch.push(`${TERMS.holder} ${a.own}→${b.own}`);}
 return guTabName(UI.tab)+(ch.length?'：'+ch.join('、'):'的修改');}
function guOnSave(){if(GU.mute||typeof STORE==='undefined'||!STORE)return;if(typeof CLOUD!=='undefined'&&CLOUD.mode==='visitor')return;
 if(GU.ref!==STORE||GU.last==null){guReset();guBar();return;}
 let now;try{now=guSer();}catch(e){return;}if(now===GU.last)return;const cnt=guCount();const t=Date.now();
 const top=GU.undo[GU.undo.length-1];
 if(top&&t-GU.at<800&&top.tab===UI.tab){top.label=guLabel(top.cnt,cnt);}
 else{GU.undo.push({snap:GU.last,cnt:GU.cnt,label:guLabel(GU.cnt,cnt),tab:UI.tab,at:t});if(GU.undo.length>GU.MAX)GU.undo.shift();}
 GU.redo=[];GU.last=now;GU.cnt=cnt;GU.at=t;guBar();}
