function subList(kind){if(kind==='fold'){if(!Array.isArray(S.folders))S.folders=[];return S.folders;}if(kind==='acc'){if(!Array.isArray(STORE.accSub))STORE.accSub=[];return STORE.accSub;}
 S.subcats=S.subcats&&typeof S.subcats==='object'&&!Array.isArray(S.subcats)?S.subcats:{};if(!Array.isArray(S.subcats[kind]))S.subcats[kind]=[];return S.subcats[kind];}
