function ptryData(b){if(!b)return null;if(b.look)return{v:1,id:b.id||'',nick:b.nick||'',look:{w:b.look.w,h:b.look.h,pose:b.look.pose||'',parts:b.look.parts,anchors:b.look.anchors||{}}};if(b.tpl)return{v:2,id:b.id||'',nick:b.nick||'',pose:b.tpl.pose,pal:b.tpl.pal};return null;}
