function tpvScan(){const st=tpvStyle();const all=[],stale=[];
 const add=(o,src,f,U,sc)=>{const k=tpvKey(src,o.w,o.h,o.x,o.y,f);const us=sc&&sc!==1?sc:0;const t={o,src,w:o.w,h:o.h,x:o.x,y:o.y,f,k,st,U,sc:us};all.push(t);if(!o.pv||o.pv.k!==k||o.pv.st!==st||(+o.pv.u||0)!==us)stale.push(t);};
 (STORE.acc||[]).forEach(a=>{if(a.hide)return;(a.arts||[]).forEach(art=>{const f=tpvF(art.w,art.h);(art.pieces||[]).forEach(pc=>{if(pc.hid)return;const src=imgSrc(pc.img);if(src)add(pc,src,f,Math.max(+art.w||0,+art.h||0));});});});
 STORE.species.forEach(sp=>{const p=pubCfg(sp);if(!p.on||p.tryon===0)return;withSpecies(sp,()=>sp.inds.forEach(ind=>{if(!indTryPub(ind)||!pubVisible(ind,p))return;const r=tpvIndParts(ind);if(!r)return;r.L.flat.parts.forEach(x=>{const src=imgSrc(x.img);if(src)add(x,src,r.f,Math.max(+r.L.w||0,+r.L.h||0));});}));
  /* 第 163 版：未持有棲息地的立體預覽——每一層印水印 */withSpecies(sp,()=>tpvHabEach((o,src,U,sc)=>add(o,src,1,U,sc)));});
 return{all,stale};}
