function tpvDrop(img){if(!img)return;dropAsset(img);if(img.id){const c=tpvCfg();c.ids=c.ids.filter(x=>x!==img.id);}}
function tpvSweep(){const c=tpvCfg();if(!c.ids.length)return;const keep=new Set();const see=o=>{if(o&&o.pv&&o.pv.img&&o.pv.img.id)keep.add(o.pv.img.id);};
 (STORE.acc||[]).forEach(a=>(a.arts||[]).forEach(art=>(art.pieces||[]).forEach(see)));STORE.species.forEach(sp=>{sp.inds.forEach(i=>{const L=i.look;if(L&&L.flat&&Array.isArray(L.flat.parts))L.flat.parts.forEach(see);});/* 第 163 版 */const hs=(rmCfg(sp).hab)||{};Object.values(hs).forEach(hc=>{see(hc);(hc&&hc.layers||[]).forEach(see);});});
 c.ids.filter(id=>!keep.has(id)).forEach(id=>dropAsset({id}));c.ids=c.ids.filter(id=>keep.has(id));}
async function tpvRun(){if(TPV.busy){TPV.again=true;return TPV.p;}TPV.busy=true;tpvStatUpd();
 TPV.p=(async()=>{let n=0;try{for(let round=0;round<5;round++){TPV.again=false;const L=tpvScan().stale;if(!L.length)break;let ok=0;
    for(const t of L){try{const img=await tpvMake(t);const old=t.o.pv;t.o.pv={img,k:t.k,st:t.st,...(t.sc?{u:t.sc}:{})};if(img&&img.id){const c=tpvCfg();if(!c.ids.includes(img.id))c.ids.push(img.id);}if(old&&old.img&&!(img&&old.img.id&&old.img.id===img.id))tpvDrop(old.img);ok++;}catch(e){TPV.err++;}}
    n+=ok;if(!ok||!TPV.again&&!tpvScan().stale.length)break;}
   tpvSweep();if(n)tpvSaveQuiet();}
  finally{TPV.busy=false;TPV.p=null;tpvStatUpd();}return n;})();return TPV.p;}
function tpvSaveQuiet(){GU.mute=true;try{save();}finally{GU.mute=false;}/* 第 103 版：動畫工作室有未儲存的變更時，這次沒有寫入，還原的基準不動 */if(typeof STUS!=='undefined'&&STUS.dirty)return;try{if(GU.ref===STORE){GU.last=guSer();GU.cnt=guCount();}}catch(e){}}
function tpvKick(){if(TPV.busy||TPV.t||/* 第 166 版：棲息地原圖轉檔中，做完會再叫一次 */HWP.busy)return;if(!ASSETS||typeof CLOUD==='undefined'||CLOUD.mode==='visitor'||CLOUD.loading)return;if(!tpvScan().stale.length)return;TPV.t=setTimeout(()=>{TPV.t=null;tpvRun().catch(()=>{});},800);}
function accPubArts(a){return(Array.isArray(a.arts)?a.arts:[]).map(x=>{const f=tpvF(x.w,x.h);const vis=(x.pieces||[]).filter(pc=>!pc.hid&&imgSrc(pc.img));if(!vis.length||!vis.every(pc=>tpvReady(pc,imgSrc(pc.img),f,Math.max(+x.w||0,+x.h||0))))return null;
  return{sp:x.sp||'',pose:x.pose||'',w:x.w,h:x.h,ref:clone(accRefPose(x)),adj:clone(x.adj||{}),pieces:vis.map(pc=>({u:pubImgSrc(pc.pv.img),x:pc.x,y:pc.y,w:pc.w,h:pc.h,after:pc.after||'',blend:pc.blend||'',op:pc.op==null?1:pc.op,role:pc.role||'',ck:pc.ck||''}))};}).filter(Boolean);}
