async function tpvSample(){const cv=document.querySelector('.tpv-sample');if(!cv)return;const tk=++TPV_SMP;const W=1200,Hh=500;const c=document.createElement('canvas');c.width=W;c.height=Hh;const x=c.getContext('2d');
 const g=x.createLinearGradient(0,0,W,Hh);g.addColorStop(0,'#3d8f9e');g.addColorStop(1,'#d9a35a');x.fillStyle=g;x.beginPath();x.ellipse(W*.36,Hh*.52,W*.3,Hh*.4,0,0,Math.PI*2);x.fill();x.fillStyle='#2b2b2b';x.beginPath();x.ellipse(W*.76,Hh*.45,W*.16,Hh*.3,.4,0,Math.PI*2);x.fill();/* 第 164 版：挖一個洞，看得到範圍內透明處的字 */x.globalCompositeOperation='destination-out';x.beginPath();x.ellipse(W*.36,Hh*.52,W*.13,Hh*.18,0,0,Math.PI*2);x.fill();x.globalCompositeOperation='source-over';
 await tpvPaint(x,W,Hh,0,0,W);await tpvRangeFrames({frames:[c]},{C:tpvPub(),U:W});if(tk!==TPV_SMP)return;/* 第 164 版：樣張＝圖（含範圍內的透明處）＋預覽頁一層 */const C=tpvPub();const ov=+C.opP>0?await tpvOverlay(C,W,Hh):null;if(tk!==TPV_SMP)return;const o=cv.getContext('2d');o.clearRect(0,0,cv.width,cv.height);o.fillStyle='#14141c';o.fillRect(0,0,cv.width,cv.height);o.drawImage(c,0,0,cv.width,cv.height);if(ov)o.drawImage(ov,0,0,cv.width,cv.height);}
function tpvRangeSolid(C){const op=Math.min(1,Math.max(.05,+C.opB||.42));const c=/^#[0-9a-f]{6}$/i.test(C.color)?C.color:'#ffffff';const mix=(i,b)=>Math.round(b+(parseInt(c.slice(i,i+2),16)-b)*op).toString(16).padStart(2,'0');return'#'+mix(1,10)+mix(3,10)+mix(5,15);}
function okGen(){const b=crypto.getRandomValues(new Uint8Array(16));return okFmt([...b].map(x=>OK_A[x&31]).join(''));}
async function okKid(k){const h=new Uint8Array(await crypto.subtle.digest('SHA-256',okEnc('algarance-kid|'+okNorm(k))));return[...h].slice(0,16).map(x=>x.toString(16).padStart(2,'0')).join('');}
async function okAes(k){const base=await crypto.subtle.importKey('raw',okEnc('algarance-key|'+okNorm(k)),'PBKDF2',false,['deriveKey']);
 return crypto.subtle.deriveKey({name:'PBKDF2',salt:okEnc('algarance-owner-v1'),iterations:150000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
async function okSeal(k,obj){const key=await okAes(k);const iv=crypto.getRandomValues(new Uint8Array(12));const ct=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,okEnc(JSON.stringify(obj))));return{iv:okB64(iv),ct:okB64(ct)};}
async function okOpen(k,d){const key=await okAes(k);const pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:okUnb64(d.iv)},key,okUnb64(d.ct));return JSON.parse(new TextDecoder().decode(pt));}
function okPayload(w){const inds=[];
 ownerInds(w.id).forEach(({sp,ind})=>withSpecies(sp,()=>{const p=pubCfg(sp);if(!p.on||p.tryon===0)return;const lk=pubLook(ind);const po=poseOf(ind);if(!lk&&!po)return;
  inds.push({sp:spKey(sp),id:ind.id,nick:ind.nick||'',sex:ind.sex,look:lk||null,pose:lk?'':po.id,pal:lk?null:palOf(ind),/* 第 162 版：共同飼主的鑰匙——個體共用，飾品只帶自己持有的 */wear:indAcc(ind,spKey(sp)).filter(x=>instOwner(x)===w.id).map(x=>({acc:x.acc,slot:x.slot}))});}));
 const A=ownerAssets(w.id);const accs={};[...new Set(A.inst.map(x=>x.acc))].forEach(id=>{const a=accById(id);if(!a)return;const arts=accArtsFull(a);if(!arts.length)return;/* 第 169 版：剩餘數量不放進鑰匙內容，領取數一變才不會每把鑰匙都重新加密 */const {claim:_cl,...cp}=catPub(a,'acc');
  accs[id]={id:a.id,name:a.name,kind:a.kind||'',...cp,slots:(a.slots||[]).map(k=>({k,n:wearName(k)})),species:a.species,wear:{},arts,...accColPub(a),n:A.inst.filter(x=>x.acc===id).length};});
 /* 第 100 版：已持有的棲息地與小房間設定（我的養殖艙） */let rooms={};try{if(typeof mrPayload==='function')rooms=mrPayload(w);}catch(e){console.error(e);}
 /* 第 169 版：已領過或已持有的領取輪次 */const done=claimDoneFor(w);return{v:1,owner:{id:w.id,name:w.name||''},inds,accs,rooms,...(done.length?{claimDone:done}:{})};}
function okBuild(w,K,pl,sig){const bk=K.kid+'|'+sig;if(OKEY.busy.has(bk))return OKEY.busy.get(bk);if(!okReady()){OKEY.err.set(w.id,'這個瀏覽器不支援加密');return null;}
 const pr=(async()=>{try{let s=await okSeal(K.k,pl);if(s.ct.length>230000)s=await okSeal(K.k,{...okStrip(pl),trim:1});if(s.ct.length>240000)throw new Error('內容太大（個體或飾品太多）');
   const doc={id:K.kid,v:1,h:sig,at:new Date().toISOString(),...s};OKEY.done.set(K.kid,{sig,doc});OKEY.err.delete(w.id);if(typeof CLOUD!=='undefined'&&CLOUD.mode==='owner')scheduleSync();}
  catch(e){OKEY.err.set(w.id,String((e&&e.message)||e));}finally{OKEY.busy.delete(bk);}})();OKEY.busy.set(bk,pr);return pr;}
function okDocs(m){if(!STORE.species.some(sp=>pubCfg(sp).on))return;
 STORE.owners.forEach(w=>{const K=w.key;if(!K||!K.k||!K.kid)return;let pl;try{pl=okPayload(w);}catch(e){console.error(e);return;}const sig=okSig(pl,K);const path=okPath(K.kid);
  const d=OKEY.done.get(K.kid);if(d&&d.sig===sig){m.set(path,d.doc);return;}
  const prev=typeof CLOUD!=='undefined'&&CLOUD.last&&CLOUD.last.get(path);if(prev){try{const o=JSON.parse(prev);if(o&&o.h===sig){OKEY.done.set(K.kid,{sig,doc:o});m.set(path,o);return;}if(o)m.set(path,o);}catch(e){}}
  okBuild(w,K,pl,sig);});}
async function okBuildAll(){okDocs(new Map());await Promise.all([...OKEY.busy.values()]);}
function okMsg(w){return`【Algarance Black Market ${TERMS.owner}鑰匙】\n${w.name||w.id} 你好，這是你的專屬鑰匙：\n${w.key.k}\n\n在公開頁「模擬養殖」的養殖艙入口輸入鑰匙後，就能用自己的個體換裝，已持有的飾品會是清晰的正式圖，也可以下載圖片。\n下載的正式穿搭圖會附上驗證碼，任何人都能在公開頁的「${TERMS.owner}展示櫃」查詢。\n鑰匙請不要分享給別人；如果外流了請告訴我，我會換一把新的（舊的會立刻失效）。`;}
