async function okImgs(pl){const found=new Map();const walk=v=>{if(typeof v==='string'){if(v.includes('gcm:'))for(const m of v.matchAll(OK_GCM))found.set(m[0],m);return;}if(v&&typeof v==='object')Object.values(v).forEach(walk);};walk(pl);if(!found.size)return pl;
 const un=s=>Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));const ok=new Map();const L=[...found.values()];let i=0;
 await Promise.all(Array.from({length:Math.min(6,L.length)},async()=>{while(i<L.length){const m=L[i++];try{const r=await fetch(m[1]);if(!r.ok)throw new Error(r.status);const u=new Uint8Array(await r.arrayBuffer());const key=await crypto.subtle.importKey('raw',un(m[2]),'AES-GCM',false,['decrypt']);const pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:u.subarray(0,12)},key,u.subarray(12));ok.set(m[0],URL.createObjectURL(new Blob([pt],{type:m[3]})));}catch(e){console.error('鑰匙內容的圖片讀取失敗',m[1],e);ok.set(m[0],'');}}}));
 const rep=v=>{if(typeof v==='string')return v.includes('gcm:')?v.replace(OK_GCM,s=>ok.get(s)||''):v;if(Array.isArray(v)){v.forEach((x,k)=>{v[k]=rep(x);});return v;}if(v&&typeof v==='object'){Object.keys(v).forEach(k=>{v[k]=rep(v[k]);});}return v;};rep(pl);return pl;}
