function evState(e){const t=evToday();const s=e.start||'',en=e.end||e.start||'';if(!s)return{k:'on',n:'進行中'};if(en&&en<t)return{k:'end',n:'已結束'};if(s>t){const d=Math.round((new Date(s)-new Date(t))/864e5);return{k:'soon',n:d<=1?'明天開始':`${d} 天後開始`};}return{k:'on',n:'進行中'};}
