function gifDecode(buf,full){const L=window.GIFLIB;const g=L.parseGIF(buf);const fr=L.decompressFrames(g,true);if(!fr.length)throw new Error('GIF 沒有影格');
 const W=g.lsd.width,Hh=g.lsd.height;let k=full?1:Math.min(1,GIF_MAX_SIDE/Math.max(W,Hh));const n=Math.min(fr.length,GIF_MAX_FRAMES);while(!full&&W*Hh*k*k*4*n>350e6&&k>.1)k*=.8;
 const main=document.createElement('canvas');main.width=W;main.height=Hh;const mx=main.getContext('2d',{willReadFrequently:true});const pc=document.createElement('canvas');const px=pc.getContext('2d');
 const frames=[],delays=[];let prev=null,saved=null;
 for(let i=0;i<n;i++){const f=fr[i];if(prev){if(prev.disposalType===2)mx.clearRect(prev.dims.left,prev.dims.top,prev.dims.width,prev.dims.height);else if(prev.disposalType===3&&saved)mx.putImageData(saved,0,0);}
  saved=f.disposalType===3?mx.getImageData(0,0,W,Hh):null;
  pc.width=f.dims.width;pc.height=f.dims.height;px.putImageData(new ImageData(new Uint8ClampedArray(f.patch),f.dims.width,f.dims.height),0,0);mx.drawImage(pc,f.dims.left,f.dims.top);
  const o=document.createElement('canvas');o.width=Math.max(1,Math.round(W*k));o.height=Math.max(1,Math.round(Hh*k));o.getContext('2d').drawImage(main,0,0,o.width,o.height);frames.push(o);delays.push(Math.max(20,+f.delay||100));prev=f;}
 const live=document.createElement('canvas');live.width=W;live.height=Hh;live.getContext('2d').drawImage(frames[0],0,0,W,Hh);live.naturalWidth=W;live.naturalHeight=Hh;
 const G={w:W,h:Hh,k,frames,delays,total:delays.reduce((a,b)=>a+b,0),live,cur:0};live.gif=G;return G;}
function gifSetTime(t,only){(only||[...GIFS.values()]).forEach(G=>{const i=gifIdx(G,t);if(i===G.cur)return;G.cur=i;const x=G.live.getContext('2d');x.clearRect(0,0,G.w,G.h);x.drawImage(G.frames[i],0,0,G.w,G.h);});}
async function gifLoad(src){const u=src.replace(/#gif$/,'');const r=await fetch(u);if(!r.ok)throw new Error('load');const G=gifDecode(await r.arrayBuffer());G.src=src;GIFS.set(src,G);return G.live;}
function gifTimeline(Gs){if(!Gs.length)return null;const step=Math.max(40,Math.min(...Gs.map(G=>Math.min(...G.delays))));const total=Math.min(GIF_MAX_MS,Math.max(...Gs.map(G=>G.total)));const n=Math.max(1,Math.min(GIF_MAX_FRAMES,Math.round(total/step)));return{step,n};}
function gifEncode(frames,delay,o){o=o||{};const {GIFEncoder,quantize,applyPalette}=window.GIFLIB;const g=GIFEncoder();
 frames.forEach((c,i)=>{let src=c;if(o.bg){src=document.createElement('canvas');src.width=c.width;src.height=c.height;const x=src.getContext('2d');x.fillStyle=o.bg;x.fillRect(0,0,c.width,c.height);x.drawImage(c,0,0);}
  const d=src.getContext('2d',{willReadFrequently:true}).getImageData(0,0,src.width,src.height).data;
  if(o.bg){const pal=quantize(d,256,{format:'rgb565'});g.writeFrame(applyPalette(d,pal,'rgb565'),src.width,src.height,{palette:pal,delay:Array.isArray(delay)?delay[i]:delay});}
  else{const pal=quantize(d,256,{format:'rgba4444',oneBitAlpha:true,clearAlpha:true,clearAlphaThreshold:127});const idx=applyPalette(d,pal,'rgba4444');const ti=pal.findIndex(p=>p[3]===0);
   g.writeFrame(idx,src.width,src.height,{palette:pal,delay:Array.isArray(delay)?delay[i]:delay,transparent:ti>=0,transparentIndex:Math.max(0,ti),dispose:2});}});
 g.finish();return new Blob([g.bytes()],{type:'image/gif'});}
async function gifPut(blob){const r=await putRaw(blob);if(r&&r.url&&!/#gif$/.test(r.url))r.url+='#gif';return r;}
function gifBox(G){let x1=Infinity,y1=Infinity,x2=-1,y2=-1;G.frames.forEach(c=>{const d=c.getContext('2d',{willReadFrequently:true}).getImageData(0,0,c.width,c.height).data;const w=c.width;
  for(let y=0;y<c.height;y++)for(let x=0;x<w;x++)if(d[(y*w+x)*4+3]>8){if(x<x1)x1=x;if(x>x2)x2=x;if(y<y1)y1=y;if(y>y2)y2=y;}});
 if(x2<0)return null;const k=G.k;return{x:Math.floor(x1/k),y:Math.floor(y1/k),w:Math.ceil((x2-x1+1)/k),h:Math.ceil((y2-y1+1)/k)};}
