 if(full){x=b.x;y=b.y;w=b.w;h=b.h;}else{const s=Math.min((+o.w||b.w)/b.w,(+o.h||b.h)/b.h);w=Math.max(1,Math.round(b.w*s));h=Math.max(1,Math.round(b.h*s));x=Math.round((+o.x||0)+((+o.w||w)-w)/2);y=Math.round((+o.y||0)+((+o.h||h)-h)/2);}
