 const list=rows.map(r=>`<li data-lid="${H(r.id)}"><div class="lyr-r${r.id===sel?' on':''}${r.hide?' off':''}"><button type="button" class="lyr-rb" data-pst="sel|${H(r.id)}" aria-pressed="${r.id===sel}"${perm.full?' title="點一下選取；按住上下拖曳＝調整前後（Alt＋↑↓ 也可以）"':' disabled'}><span class="lyr-th"><canvas data-lid="${H(r.id)}" width="36" height="36"></canvas></span><span class="lyr-n">${H(r.n)}</span></button><button type="button" class="lyr-eye" data-pst="lhide|${H(r.id)}" aria-pressed="${!r.hide}" aria-label="${r.hide?'顯示':'隱藏'}${H(r.n)}" title="${r.hide?'顯示':'隱藏'}"${perm.full?'':' disabled'}>${r.hide?'○':'●'}</button></div></li>`).join('');
