  /* 轉過的元素取外接方框 */const c=Math.abs(Math.cos(h.r||0)),s=Math.abs(Math.sin(h.r||0));const bw=h.w*c+h.h*s,bh=h.w*s+h.h*c;const sx=Math.max(0,h.cx-bw/2),sy=Math.max(0,h.cy-bh/2);const sw=Math.min(cv.width-sx,bw),sh=Math.min(cv.height-sy,bh);if(sw<1||sh<1)return;
