function pstTxtDef(x,scan){const r=scan.runs[0];const lines=pstTxtLines(x,scan.runs);const ys=[...new Set(scan.runs.map(q=>Math.round(q.y)))].sort((a,b)=>a-b);const px0=pstTxtPx(r.font);let lh=120;if(ys.length>1){const gaps=ys.slice(1).map((y,i)=>y-ys[i]);lh=Math.round(gaps.reduce((a,b)=>a+b,0)/gaps.length/px0*100);}return{lh:Math.max(70,Math.min(260,lh)),al:r.al==='center'?'c':(r.al==='right'||r.al==='end')?'r':'l',lines};}
function pstTxtDraw(x,W,Hh,scan,t,d){const k=(+t.fs||100)/100,lhK=(+t.lh||d.lh)/100,al=t.al||d.al,va=t.va||'',vert=t.dir==='v';const cjk='\\u2E80-\\u9FFF\\uF900-\\uFAFF\\uFF00-\\uFFEF';const tk=new RegExp(`[${cjk}]|[^\\s${cjk}]+|\\s+`,'g');
 x.save();x.textBaseline='alphabetic';x.textAlign='left';const put=(q,X,Y)=>{x.font=q.font;x.fillStyle=q.fill;x.globalAlpha=q.a;try{x.letterSpacing=q.ls;}catch(er){}x.fillText(q.t,X,Y);};const items=[];
 d.lines.forEach(rs=>{const row=[];rs.forEach((r,i)=>{const font=pstTxtFont(r.font,k);x.font=font;(r.s.match(tk)||[]).forEach(s=>row.push({t:s,font,fill:r.fill,a:r.a,ls:r.ls,sp:/^\s+$/.test(s),px:pstTxtPx(font)}));if(i<rs.length-1){x.font=r.font;const end=r.x+x.measureText(r.s).width;const gap=rs[i+1].x-end;if(gap>1)row.push({t:' ',font,fill:r.fill,a:r.a,ls:r.ls,sp:true,px:pstTxtPx(font)});}});items.push(row);});
 if(vert){const cols=[];items.forEach(row=>{let col=[],h=0;const flush=()=>{if(col.length)cols.push(col);col=[];h=0;};row.forEach(q=>{if(q.sp)return;[...q.t].forEach(ch=>{const a=q.px*1.04;if(h+a>Hh+.5&&col.length)flush();col.push({...q,t:ch,adv:a});h+=a;});});flush();});
  const cw=(cols[0]&&cols[0][0]?cols[0][0].px:16)*Math.max(.9,lhK);const tw=cols.length*cw;const x0=al==='l'?tw-cw:al==='r'?W-cw:(W+tw)/2-cw;x.textAlign='center';cols.forEach((col,i)=>{const h=col.reduce((a,q)=>a+q.adv,0);let y=va==='b'?Hh-h:va==='m'?(Hh-h)/2:0;const X=x0-i*cw+cw/2;col.forEach(q=>{y+=q.adv;put(q,X,y-q.px*.12);});});x.restore();return;}
 const lines=[];items.forEach(row=>{let cur=[],w=0;const flush=()=>{while(cur.length&&cur[cur.length-1].sp){w-=cur[cur.length-1].w;cur.pop();}lines.push({rs:cur,w});cur=[];w=0;};row.forEach(q=>{x.font=q.font;const a=x.measureText(q.t).width;if(q.sp&&!cur.length)return;if(w+a>W+.5&&cur.length&&!q.sp)flush();if(q.sp&&!cur.length)return;cur.push({...q,w:a});w+=a;});flush();});
 const pxOf=l=>Math.max(1,...l.rs.map(q=>q.px));const th=lines.reduce((a,l)=>a+pxOf(l)*lhK,0);const first=d.lines[0]?Math.min(...d.lines[0].map(r=>r.y)):0;let y=va==='b'?Hh-th:va==='m'?(Hh-th)/2:va==='t'?0:Math.max(0,first-pxOf(lines[0]||{rs:[]})*.95);
 lines.forEach(l=>{const p=pxOf(l);const base=y+p*.95;let X=al==='r'?W-l.w:al==='c'?(W-l.w)/2:0;l.rs.forEach(q=>{put(q,X,base);X+=q.w;});y+=p*lhK;});x.restore();}
