async function assetAlive(id){if(!id)return false;try{if(JSON.stringify(STORE).includes(id))return true;}catch(e){}
 try{if(ASSETS&&typeof ASSETS.list==='function'){const A=await astLoad(false);return!!(A&&A.list&&A.list.some(a=>a.id===id));}}catch(e){}return false;}
