function v77Norm(l,v){const tot=locTot(l,v)||0;if(!(tot>0))return;l.alleles.forEach(a=>{const nv=Math.round(freqFor(l,a,v)/tot*10000)/10000;if(v)a.vf={...(a.vf||{}),[v]:nv};else a.f=nv;});}
