 /* 異型合子名稱：同一個新基因座內的寫成那個基因座的名稱；跨基因座的變成組合名稱規則 */
 const lab=String(l.labels||'').split('\n').map(x=>x.trim()).filter(x=>x.includes('='));const newRules=[];const homLab=new Set();
 const pairCond=(a,b)=>P.loci.map(n=>{const x=P.map[a][n.sym],y=P.map[b][n.sym];return x===y?`${n.sym}^${x}:hom`:`${n.sym}^${x}:het & ${n.sym}^${y}:het`;}).join(' & ');
 lab.forEach(line=>{const [pp,...rest]=line.split('=');const nm=rest.join('=').split('|');const zh=(nm[0]||'').trim(),en=(nm[1]||'').trim();const [a,b]=pp.split('/').map(s=>s.trim());if(!P.map[a]||!P.map[b])return;
  if(!en){add('異型合子名稱',line,'（沒有英文名稱，原本就不顯示，略過）','warn');return;}if(a===b)homLab.add(a);newRules.push({cond:pairCond(a,b),hide:'',slot:l.slot||'',zh,en,col:a===b&&P.color?(IDX.al[l.sym][a]||{}).col||'':'',note:`拆解 ${P.old}：${a}/${b}`,ren:NS.join(','),gen:'split:'+P.old});add('異型合子名稱',line,'組合名稱規則：'+pairCond(a,b),'auto');});
