 S.loci.splice(ix,1,...nl);newRules.forEach(r=>{const same=!r.ren&&!r.zh&&!r.en&&!r.col&&S.epistasis.find(x=>x.cond===r.cond&&!x.zh&&!x.en&&!x.col);if(same){same.hide=[...new Set(String(same.hide||'').split(/[,\s]+/).concat(String(r.hide).split(/[,\s]+/)).filter(Boolean))].join(',');add('遮蓋規則',r.cond,'併入現有規則：遮蓋 '+same.hide,'auto');}else S.epistasis.push(r);});
