function amToolInfo(){const el=document.getElementById('stu-toolinfo');if(!el)return;if(RM.pick){el.innerHTML='<b>設定轉軸</b>：在預覽圖上點轉軸要在的位置';return;}const t=AM_TOOLS.find(x=>x[0]===STU.tool)||AM_TOOLS[1];
 el.innerHTML=STU.tool==='view'&&amView()!=='ind'?H(t[2]):STU.sel?`選取：<b>${H(amSelName(STU.sel))}</b>　${amMovable(STU.sel)&&amView()!=='ind'?H(t[2]):'（可以在右邊調整）'}`:(amView()==='ind'?'點預覽圖上的部位來選取':amView()==='hab'?'點預覽圖上的物件來選取（棲息地圖層、地面）':'點預覽圖上的物件來選取（生物；再點一下生物＝選部位；棲息地圖層、地面）');}
function amLayersHtml(){const v=amView();const R=rmCfg();const off=amOff();const ind=v==='hab'?(amPreviewOther()?stuCurInd():null):stuCurInd();const code=v==='ind'?'':STU.hab;const sel=STU.sel||'';
 /* 第 171 版：眼睛只影響預覽（STU.pvOff，不存檔）；輸出要不要包含在屬性面板設定（data-stuoff） */const eye=k=>off.has(k)?`<span class="lyr-eye lyr-noout" title="已設定輸出時隱藏（在右邊的屬性面板改）">✕</span>`:`<input type="checkbox" class="lyr-eye" data-stupv="${H(k)}"${STU.pvOff.has(k)?'':' checked'} aria-label="預覽時顯示" title="只影響預覽，不改設定">`;const mv=k=>`<span class="lyr-mv"><button type="button" class="g mini" data-stu="zmv|${H(k)}|up" title="往前">↑</button><button type="button" class="g mini" data-stu="zmv|${H(k)}|down" title="往後">↓</button></span>`;
 const th=src=>src?`<img class="lyr-th" src="${H(src)}" alt="">`:'<span class="lyr-th"></span>';
 const row=(k,inner,opts={})=>`<div class="lyr${sel===k?' lyr-on':''}${opts.sub?' sub':''}">${opts.noEye?'<span class="lyr-eye"></span>':eye(opts.eyeKey||k)}<button type="button" class="lyr-b" data-stu="pk|${H(k)}">${inner}</button>${opts.mv?mv(k):''}</div>`;
 const out=[];const partRows=()=>{const lk=ind&&farmLook(ind);if(!lk)return;const parts=lk.parts;const rootK=parts.length?rmRootOf(parts).k:'';
  parts.slice().reverse().forEach(p=>{const c=rmPartCfg(R,p,ind);const mk=p.k===rootK?((amPartRaw(R,rootK,ind)||{}).mat||'breathe'):c.mat;out.push(row('part:'+p.k,`<span>${H(p.n||p.k)}${p.k===rootK?'<span class="tiny muted">（根）</span>':''}</span>${amPartDots(ind,p.k)}<span class="chip">${H(amMatName(mk))}</span>`,{sub:1}));});};
 const indRow=prev=>{out.push(row('ind',`${th(((ind.imgs||[])[0]&&imgSrc(ind.imgs[0]))||'')}<span><b>★ ${H(ind.id)}</b>${ind.nick?' '+H(ind.nick):''}${prev?'<br><span class="tiny muted">預覽：調整的是棲息地預設位置</span>':''}</span><span class="chip">個體</span>`,{noEye:1,mv:v!=='ind'}));partRows();};
 if(v==='ind'){if(ind)indRow(false);}
 else if(code){const ctx=stuCtx();const items=amStackItems(ctx).slice().reverse();
  items.forEach(it=>{if(it.key==='ind'){if(ind)indRow(ctx.k==='hab');return;}
   if(it.key==='floor'){const hc=R.hab[code]||{};const f=hc.floor&&amFloor(hc.floor);out.push(row('floor',`${th(f&&f.img&&imgSrc(f.img))}<span>地面<br><span class="tiny muted">${f?H(f.n||''):'自動（碎石）'}</span></span><span class="chip">地面</span>`,{mv:1}));return;}
   const l=it.l;out.push(row(it.key,`${th(l.img&&!l.gif&&imgSrc(l.img))}<span>${H(l.n||'圖層')}${l.gif?' <span class="tiny muted">GIF</span>':''}</span>${amLayerDots(l)}<span class="chip">${H(amMatName(l.mat))}</span>`,{mv:1}));});
  const Ls=amHabLayers(code);const clips=Ls.map((l,i)=>({l,i})).filter(({l,i})=>amClipOf(l,i));
  if(clips.length){out.push('<div class="lyr-g">貼在後牆</div>');clips.forEach(({l})=>out.push(row('wl:'+l.id,`${th(l.img&&!l.gif&&imgSrc(l.img))}<span>${H(l.n||'圖層')}</span>${amLayerDots(l)}<span class="chip">${H(amMatName(l.mat))}</span>`)));}}
 const room=v==='ind'?'':`<div class="lyr-g">房間（輸出也會跟著改）</div><div class="stu-checks">${[['bg','背景'],['wall','後牆'],['sides','側牆倒影'],['water','水面'],['rim','牆的厚度'],['lines','牆角線'],['frame','外框'],['plate','名牌'],['bubbles','特效'],['shadow','影子'],['owner',TERMS.owner+' ID']].map(([a,b])=>`<label class="tiny st-chk"><input type="checkbox" data-stuoff="${a}"${off.has(a)?'':' checked'}>${b}</label>`).join('')}</div>`;
 const up=code&&v!=='ind'?`<div class="lyr-up"><label class="b mini imgadd" style="width:auto;height:auto;padding:5px 10px">上傳分層 PSD<input type="file" accept="image/*,.psd,image/vnd.adobe.photoshop" data-rmwall="${H(code)}" hidden></label><label class="g mini imgadd" style="width:auto;height:auto;padding:5px 10px">＋ PNG／GIF 圖層<input type="file" accept="image/*" data-rmlayer="${H(code)}" hidden></label><label class="g mini imgadd" style="width:auto;height:auto;padding:5px 10px">＋ 地面<input type="file" accept="image/*" data-stuhabfloor="${H(code)}" hidden></label></div>`:'';
 return`<div class="lyr-h"><b>圖層</b><span class="tiny muted">${v==='ind'?'':'前 ↑　後 ↓'}</span>${ind?'<span class="tiny muted lyr-leg" title="每個部位設定到哪裡：轉軸、動作、立體。藍色＝這隻自己調的，灰色＝模板或物種的">軸 動 體</span>':code&&amHabLayers(code).length?'<span class="tiny muted lyr-leg" title="每一層設定到哪裡：轉軸、材質與動作、位置與立體。藍色＝調過">軸 動 位</span>':''}<button type="button" class="g mini" data-stu="pk|" style="margin-left:auto"${sel?'':' aria-pressed="true"'} title="不選任何東西＝場景設定">場景設定</button></div>
 <div class="lyr-list">${out.join('')||'<p class="tiny muted">還沒有內容。</p>'}</div>${room}${up}`;}
function amInspLayer(code,id){const R=rmCfg();const Ls=amHabLayers(code);const i=Ls.findIndex(l=>l.id===id);if(i<0)return'<p class="tiny muted">找不到這一層。</p>';const l=Ls[i];const base=!!l.full;/* 第 106 版：路徑用原本圖層清單（含地面圖層）裡的位置；Ls 不含地面圖層，用 i 會改到前面幾層（使用者回報：改雲的大小改到丘陵、改名改到別層） */const ri=((R.hab[code]||{}).layers||[]).findIndex(z=>z.id===id);const P=base?`hab.${code}.base`:`hab.${code}.layers.${ri}`;const m=animMat()[l.mat||'fixed']||{};const tw=l.tw||{};
 /* 第 179 版：照個體部位的流程分成三張卡——轉軸 → 動作 → 立體（STU.ptab 和部位共用）；轉軸的點位在 1118 */
 const mo=`<div class="row rm-f">${amF("材質",amMatSel(P+".mat",l.mat,"fixed"))}${amMatBtn}</div>${base?"":`<div class="row rm-f">${amF("跟著",`<select data-rmf="${P}.parent"><option value="">不跟著</option>${Ls.filter(z=>z!==l).map(z=>`<option value="${H(z.id)}"${l.parent===z.id?" selected":""}>${H(z.n||z.id)}</option>`).join("")}</select>`)}</div>`}
  <div class="row rm-f">${amF("幅度",amSl(P+".amp",l.amp,.1,0,3,1))}${amF("多延遲",amSl(P+".lag",l.lag,.02,0,1,0))}${+m.drift?amF("方向",`<select data-rmf="${P}.dir"><option value="1"${+l.dir>=0?" selected":""}>往右</option><option value="-1"${+l.dir<0?" selected":""}>往左</option></select>`):""}</div>
  ${amSec("laymoadv","進階","抽動、半透明、輸出",`<div class="row rm-f">${amF("抽動 位置",amSl(P+".tw.at",tw.at!=null&&+tw.at>1?+tw.at/100:tw.at,.01,0,1,.5))}${amF("格數",amSl(P+".tw.len",tw.len,1,0,48,0))}${amF("角度",amSl(P+".tw.ang",tw.ang,1,-90,90,0))}</div><div class="row rm-f">${amF("半透明範圍（下限）",amSl(P+".alo",l.alo,5,0,255,50))}${amF("（上限）",amSl(P+".ahi",l.ahi,5,0,255,190))}</div>${amOutChk("wl:"+l.id,"圖層")}${amHelp("幅度＝材質動作的倍數；跟著＝跟著另一層一起動（例如花跟著莖）；半透明範圍＝透明度介於兩數之間的地方，像素版打成網點。")}`)}`;
 const d3=`<div class="chrh">位置與深度</div><div class="row rm-f">${amF("X",amSl(P+".ox",l.ox,.01,-1,1,0))}${amF("Y",amSl(P+".oy",l.oy,.01,-1,1,0))}</div><div class="row rm-f">${amF("大小",amSl(P+".sc",l.sc,.05,.1,4,1))}${amF("深度",`<span class="row" style="gap:4px;align-items:center">${amSl(P+".z",l.z,.01,0,1,+amLz(l,i,Ls.length).toFixed(2))}${l.z!=null&&l.z!==""?amAuto(P+".z"):""}</span>`)}</div>
  <div class="chrh">厚度、偏轉與缸體</div><div class="row rm-f">${amF("厚度（往後牆）",amSl(P+".th",l.th,.01,0,1,0))}${amClipOf(l,i)?"":amF("偏轉（度）",amSl(P+".yw",l.yw,1,-75,75,0))}</div><div class="row rm-f">${amF("超出缸體",amOvSel(P,l.ov))}</div>${typeof amA3On==="function"&&amA3On()&&!+l.yw?`<div class="row rm-f">${amF("鼓起（轉動時像立體的）",`<select data-rmf="${P}.inf"><option value=""${l.inf==null||l.inf===""?" selected":""}>自動（小而完整的物件才鼓）</option><option value="1"${l.inf!=null&&l.inf!==""&&+l.inf?" selected":""}>鼓起</option><option value="0"${l.inf!=null&&l.inf!==""&&!+l.inf?" selected":""}>平面</option></select>`)}${amF("鼓起的厚度",amSl(P+".infk",l.infk==null||l.infk===""?1:l.infk,.05,0,3,0))}</div>`:""}
  ${amSec("lay3dadv","進階","貼在後牆",`<label class="tiny st-chk"><input type="checkbox" data-stuclip="${H(code)}|${H(l.id)}"${amClipOf(l,i)?" checked":""}>貼在後牆（只畫在後牆範圍內）</label>`)}
  ${amHelp(`深度 0 最後、1 最前，也可以用預覽圖上方的「Z 深度」拖曳。厚度：像壓克力立牌一樣往後牆長出側面（缸深的比例，0＝沒有厚度，和缸體厚度無關），轉動或擺動時看得到；側面不會蓋住後面圖層的正面。超出缸體：預設圖層不會超出缸體，動態時突出的部分也會隱藏；可以只讓上緣（例如長出水面的植物）或下緣超出，或完全不限制（沒有側牆的舞台不裁切）。偏轉：繞這一層中央的垂直軸轉，正＝右邊往後牆、負＝左邊往後牆，像斜插進場景的招牌；底部仍站在地面上（貼在後牆的圖層沒有偏轉）。`)}`;
 return`<div class="ins-h">${l.img&&!l.gif?`<img class="lyr-th" src="${H(imgSrc(l.img))}" alt="">`:""}${base?"<b>整張圖</b>":`<input class="s" data-rmf="${P}.n" value="${H(l.n||"")}" style="width:170px">`}</div>${amPartTabs(AM_WL_TABS)}${amPane("pv",amWlPvHtml(code,l,P))}${amPane("mo",mo)}${amPane("3d",d3)}
 ${base?"":`<div class="row" style="margin-top:8px"><button type="button" class="x mini" data-rml="del|${H(code)}|${ri}">刪除這一層</button></div>`}`;}
function amPartTabs(tabs){const t=STU.ptab||'pv';return`<div class="seg pt-tabs" role="tablist">${(tabs||AM_PTABS).map(([k,n])=>`<button type="button" role="tab" data-pttab="${k}" aria-selected="${t===k}" aria-pressed="${t===k}">${n}</button>`).join('')}</div>`;}
function amInspPart(ind,k){const R=rmCfg();const lk=farmLook(ind);const parts=lk?lk.parts:[];const p=parts.find(x=>x.k===k);if(!p)return'<p class="tiny muted">找不到這個部位。</p>';const keys=parts.map(x=>x.k);const rootK=rmRootOf(parts).k;const c=rmPartCfg(R,p,ind);const P=`parts.${k}`;const root=k===rootK;
 const nm=q=>{const z=parts.find(x=>x.k===q);return z?(z.n||q):q;};const par=rmParentOf(p,keys,{},rootK);const B=amC3PartHtml(ind,p);const eye=rmIsEye(p)||rmIsClosed(p)||!!c.eye;
 const tw=amSec('moadv','進階','抽動、半透明、輸出',`<div class="row rm-f">${amF('抽動 位置',amSl(P+'.tw.at',c.tw&&c.tw.at!=null?(+c.tw.at>1?+c.tw.at/100:c.tw.at):'',.01,0,1,.5))}${amF('格數',amSl(P+'.tw.len',c.tw?c.tw.len:'',1,0,48,0))}${amF('角度',amSl(P+'.tw.ang',c.tw?c.tw.ang:'',1,-90,90,0))}</div><div class="row rm-f">${amF('半透明範圍（下限）',amSl(P+'.alo',c.alo,5,0,255,50))}${amF('（上限）',amSl(P+'.ahi',c.ahi,5,0,255,190))}</div>${eye?'':amEyeHtml(ind,p,parts,c)}${amOutChk('part:'+k,'部位')}${amHelp('幅度＝材質動作的倍數；半透明範圍＝透明度介於兩數之間的地方，像素版打成網點。')}`);
 const mo=`<div class="row rm-f">${amF('材質',root?amMatSel(P+'.mat',(amPartRaw(R,rootK,ind)||{}).mat,'breathe'):amMatSel(P+'.mat',c.mat,'normal'))}${amMatBtn}</div>${root?'':`<div class="row rm-f">${amF('跟著',`<select data-rmf="${P}.parent"><option value="">自動（${H(par?nm(par):'不跟著')}）</option><option value="-"${c.parent==='-'?' selected':''}>不跟著</option>${parts.filter(z=>z!==p).map(z=>`<option value="${H(z.k)}"${c.parent===z.k?' selected':''}>${H(z.n||z.k)}</option>`).join('')}</select>`)}</div><div class="row rm-f">${amF('幅度',amSl(P+'.amp',c.amp,.1,0,3,1))}${amF('多延遲',amSl(P+'.lag',c.lag,.02,0,1,0))}</div>`}${eye?amEyeHtml(ind,p,parts,c):''}${tw}`;
 return`<div class="ins-h"><b>${H(p.n||p.k)}</b><span class="tiny muted mono">${H(p.k)}${root?' · 根部位':rmIsEye(p)?' · 眼睛（眨眼）':rmIsClosed(p)?' · 閉眼圖':''}</span></div>${amPartTabs()}${amPane('pv',B.pts)}${amPane('mo',mo)}${amPane('3d',B.basic+B.adv)}${amScopeBar(ind,k)}`;}
function amEyeHtml(ind,p,parts,c){if(rmIsRoot(p))return'';const k=p.k;const P=`parts.${k}`;const autoE=rmIsEye(p),autoC=rmIsClosed(p);const role=c.eye||'';const isE=role==='eye'||(!role&&autoE),isC=role==='closed'||(!role&&autoC);
 const cands=parts.filter(z=>z.k!==k);return`<div class="chrh">眨眼</div><div class="row rm-f">${amF('這個部位',`<select data-rmf="${P}.eye"><option value=""${role?'':' selected'}>自動（依名稱：${autoE?'眼睛':autoC?'閉眼圖':'不是眼睛'}）</option><option value="eye"${role==='eye'?' selected':''}>眼睛（會眨眼）</option><option value="closed"${role==='closed'?' selected':''}>閉眼圖（只在眨眼時出現）</option><option value="no"${role==='no'?' selected':''}>不是眼睛</option></select>`)}
 ${isE?amF('閉眼圖',`<select data-rmf="${P}.closed"><option value=""${c.closed?'':' selected'}>自動（依名稱配對；沒有就壓扁）</option><option value="-"${c.closed==='-'?' selected':''}>不用閉眼圖（眨眼時壓扁）</option>${cands.map(z=>`<option value="${H(z.k)}"${c.closed===z.k?' selected':''}>${H(z.n||z.k)}</option>`).join('')}</select>`):''}</div>
 ${isE||isC?'<p class="tiny muted" style="margin:0">所有眼睛一起眨（時間在「整隻」的眨眼位置、閉眼格數、次數）。有閉眼圖時眨眼那幾格換成閉眼圖，沒有就把眼睛往下眼皮的位置壓扁。眼睛會自動跟著頭、貼著頭的表面。</p>':''}`;}
