 (C.seq||[]).forEach((it,si)=>{if(BD&&(si<BD.from||si>=BD.to))return;if(it.k==='floor')floorStuff();else if(it.k==='ind')crea();else if(it.k==='fx'){const c=K.fxT&&K.fxT[it.b];if(c&&C.Zfx)card(c,plane(C.Zfx[it.b]));}else{thick();const l=LYs[it.i];if(l&&l.c){const Y=amLayerYawQ(l,tb,W,H);/* 第 184 版：自動鼓起的圖層（有起伏的網格） */if(!Y&&l.inf){amGLMesh(g,l.c,0,l.y0||0,l.inf.Q,l.inf.tris,tb,cam,px,W,H);fx.drawImage(g.cv,0,0);}else if(Y){amGLCard(g,l.c,0,l.y0||0,Y.at(0),tb,cam,px,W,H,{tq:Y.tq});fx.drawImage(g.cv,0,0);}else card(l.c,lplane(l,l.Z),[0,l.y0||0]);}}});
