 if(F.rig&&F.plan&&pc)cands.push({key:'ind',z,hit:()=>{const x=Math.round(pc[0]-F.ox),y=Math.round(pc[1]-F.oy);return x>=0&&y>=0&&x<F.rig.W&&y<F.rig.H&&F.rig.parts.some(t=>t.m&&t.m[y*F.rig.W+x]);}});
 (F.wplan||[]).forEach(q=>{/* 每一層用自己的深度換回原本畫面的位置 */const pl=amV3ToBase(F,X,Y,{z:q.clip?V.tb.dd:V.lz&&V.lz[q.lid]!=null?V.lz[q.lid]:V.Zg});if(pl)cands.push({key:'wl:'+q.lid,z:q.clip?-1:q.z,hit:()=>{const fw=F.w||F.size;const x=Math.round(pl[0]),y=Math.round(pl[1]);return x>=0&&y>=0&&x<fw&&y<(F.h||F.size)&&!!(q.t.m&&q.t.m[y*fw+x]);}});});
 cands.sort((a,b)=>b.z-a.z);for(const c of cands)if(c.hit()){if(c.key==='ind'&&amView()==='ind'){const pk=amPartAt(F,pc[0],pc[1]);if(pk)return pk;}return c.key;}
