function frClose(){FR.on=false;clearInterval(FR.t);FR.fr=null;const m=document.getElementById('farmroom');if(m){m.hidden=true;m.innerHTML='';}}
function frIndFor(code){const ind=FR.ind;const real=FR.real;const p=Object.create(ind);const own=real?rmHabOf(real):'';p.room={...((real||{}).room||{}),hab:code};if(code!==own){delete p.room.dx;delete p.room.dy;delete p.room.cz;}return p;}
