 const habs=habsOf().map(h=>`<label class="fr-hab${FR.code===h.code?' on':''}"><input type="radio" name="fr-hab" data-fr="hab" value="${H(h.code)}"${FR.code===h.code?' checked':''}><b>${H(h.code)}</b> ${H(h.name||'')}</label>`).join('');
