async function mrEncode(obj){const js=JSON.stringify(obj);const z=await mrZip(okEnc(js));const body=z?'R1.'+mrB64u(z):'R0.'+mrB64u(okEnc(js));const sig=await mrHmac(body);return sig?body+'.'+sig:body;}
async function mrDecode(str){const t=String(str||'').trim().replace(/^.*[#&?]room=/,'').replace(/\s+/g,'');const m=t.match(/^(R[01])\.([A-Za-z0-9_-]+)(?:\.([A-Za-z0-9_-]+))?$/);if(!m)throw new Error('格式不對：房間'+TERMS.code+'是 R1. 開頭的一串文字');
 let u=mrUnb64u(m[2]);if(m[1]==='R1'){u=await mrZip(u,true);if(!u)throw new Error('這個瀏覽器不能讀壓縮的房間'+TERMS.code);}const obj=JSON.parse(new TextDecoder().decode(u));const sig=m[3]||'';const want=await mrHmac(m[1]+'.'+m[2]);return{obj,signed:!!sig&&sig===want};}
