function stuLeave(cb){if(STUS.t)stuStepNow();if(!STUS.dirty)return false;STUS.cb=cb;let m=document.getElementById('stu-leave');if(!m){m=document.createElement('div');m.id='stu-leave';m.className='stu-leave';m.setAttribute('role','dialog');m.setAttribute('aria-modal','true');m.setAttribute('aria-label','未儲存的變更');document.body.appendChild(m);}
 m.hidden=false;m.innerHTML=`<div class="panel stu-leave-box"><b>動畫工作室有還沒儲存的變更</b><p class="tiny muted">要先儲存嗎？不儲存的話，會回到上次儲存的樣子。</p><div class="row" style="gap:8px;justify-content:flex-end"><button type="button" class="b" data-stuleave="save">儲存</button><button type="button" class="g" data-stuleave="discard">不儲存</button><button type="button" class="g" data-stuleave="stay">留在工作室</button></div></div>`;
 const f=m.querySelector('[data-stuleave="save"]');if(f)f.focus();return true;}
