  const spd=Math.max(1,Math.min(4,Math.round(+inst.speed||1)));const col=amFxCol(inst.col||e.col||c.col);const vis=Math.max(.05,Math.min(1,+e.vis||1));const fd=+e.fade||0;
  const sz=inst.size!=null&&inst.size!==''?+inst.size:1,om=inst.op!=null&&inst.op!==''?+inst.op:1;
