 /* 第 115 版：這個部位跟著哪個模板（不指定＝這隻的姿勢） */const own=amPoseOfInd(ind);const L=amTplList();const lk=(ind.room&&ind.room.link&&ind.room.link[k])||'';
 const sel=ind.__tpl||!L.length?'':`<div class="row" style="gap:6px;align-items:center;margin-top:4px"><span class="tiny">這個部位跟著</span><select data-amlink="${H(k)}" aria-label="這個部位跟著哪個模板"><option value=""${lk?'':' selected'}>${own?`姿勢「${H(amPoseName(own))}」（預設）`:'（不跟模板）'}</option>${L.filter(t=>t.id!==own).map(t=>`<option value="${H(t.id)}"${lk===t.id?' selected':''}>${H(t.name)}${t.free?'（自訂模板）':''}</option>`).join('')}</select></div>`;
