function amPoseOpts(cur){const ps=(looksCfg().poses||[]).filter(p=>(p.layers||[]).length);if(!ps.length)return'';return`<optgroup label="姿勢模板（調給照這個姿勢畫的個體）">${ps.map(p=>`<option value="pose:${H(p.id)}"${cur==='pose:'+p.id?' selected':''}>姿勢：${H(p.name||p.id)}</option>`).join('')}</optgroup>`;}
