function amPxDither(x,W,H,o){const P=o.P;if(!P||!P.length)return;const im=x.getImageData(0,0,W,H);const a=im.data;const B=[[0,2],[3,1]];const ds=+o.dstr||0;
 for(let y=0;y<H;y++)for(let X=0;X<W;X++){const k=(y*W+X)*4;if(a[k+3]<128){a[k+3]=0;continue;}const r=a[k],g=a[k+1],b=a[k+2];const [a0,a1,d0,d1]=rmNear2(P,r,g,b);let pick=a0;
  if(ds>0){const t=Math.sqrt(d0)/(Math.sqrt(d0)+Math.sqrt(d1)+1e-6);if(t>.18)pick=(t*2*ds>(B[y%2][X%2]/4+1/8))?a1:a0;}const q=P[pick];a[k]=q[0];a[k+1]=q[1];a[k+2]=q[2];a[k+3]=255;}
 x.putImageData(im,0,0);}
function amTplCopyToPose(pid,src,ks,clr){const R=rmCfg();const S2=amPoseCfg(R,src,false);if(!S2)return;amTplBackup(pid,'套用模板之前');const D=amPoseCfg(R,pid,true);const same=amTplBase(src)===pid;
 ks.forEach(k=>{const sp=S2.parts[k];if(sp){D.parts[k]=clr?clone(sp):Object.assign(D.parts[k]||{},clone(sp));}else if(clr)delete D.parts[k];
  if(same){const v=S2.pv[k];if(Array.isArray(v))D.pv[k]=v.slice();else if(clr)delete D.pv[k];}});}
function amC3Dir(R,k,ind){const has=o=>o&&((o.za!=null&&o.za!==''&&isFinite(+o.za))||(o.z3!=null&&o.z3!==''&&isFinite(+o.z3)));const pick=o=>o.za!=null&&o.za!==''&&isFinite(+o.za)?{za:+o.za}:{z3:+o.z3};
 const I=ind&&ind.room&&ind.room.parts&&ind.room.parts[k];if(has(I))return pick(I);
 const P=ind&&typeof amPoseCfg==='function'?amPoseCfg(R,amTplOf(ind,k),false):null;const b=P&&P.parts[k];if(has(b))return pick(b);
 const a=R.parts[k];if(has(a))return pick(a);return{};}
function amC3AutoSh(t,pv,W,bb){const st=Math.max(1,Math.round(Math.max(bb[2]-bb[0],bb[3]-bb[1])/120));const pts=[];let L=0;
 for(let y=bb[1];y<=bb[3];y+=st)for(let x=bb[0];x<=bb[2];x+=st){if(!t.m[y*W+x])continue;const dx=x-pv[0],dy=y-pv[1];const d=Math.hypot(dx,dy);pts.push([dx,dy,d]);if(d>L)L=d;}
 if(pts.length<8||L<4)return'p';const bins=new Float32Array(24);let tot=0;for(const [dx,dy,d] of pts){if(d<=L*.5)continue;bins[Math.floor((Math.atan2(dy,dx)+Math.PI)/(2*Math.PI)*24)%24]++;tot++;}
 let on=0;for(const v of bins)if(v>tot*.02)on++;if(on*15>=150)return'c';const wd=pts.length*st*st/L;if(L/Math.max(1,wd)>=2.5)return'y';
 /* 第 131 版：圓圓的一團（填滿外接圓的七成以上、長寬差不多）→ 圓球 */let sx=0,sy=0;for(const [dx,dy] of pts){sx+=dx;sy+=dy;}sx/=pts.length;sy/=pts.length;let R=0;for(const [dx,dy] of pts)R=Math.max(R,Math.hypot(dx-sx,dy-sy));
 const bw=bb[2]-bb[0]+1,bh=bb[3]-bb[1]+1;return pts.length*st*st/(Math.PI*R*R+1)>=.7&&Math.max(bw,bh)/Math.max(1,Math.min(bw,bh))<1.4?'s':'p';}
function amC3GOf(k){const F=typeof RM!=='undefined'&&RM.fr;if(!F||!F.rig||!F.plan)return null;let res=null;try{res=amC3Prep(F.rig,F.plan,amC3Ind());}catch(err){return null;}for(const [t,g] of res.map)if(t.p&&t.p.k===k)return g;return null;}
