function amPanCenter(){const cv=document.getElementById('rm-cv');const F=RM.fr;if(cv&&amView()!=='ind'){STU.pan=[0,0];STU.zoom=1;amStuFit(cv,1);amPanApply(cv);amStuZoomLabel();return;}const b=F&&F.boxes&&F.boxes.ind;if(!cv||!b)return;const r=cv.getBoundingClientRect(),wr=cv.parentElement.getBoundingClientRect();const fw=F.w||F.size,fh=F.h||F.size;
 let X=(b[0]+b[2])/2,Y=(b[1]+b[3])/2;if(F.v3&&F.v3.cam&&typeof amV3ToView==='function'){const q=amV3ToView(F,X,Y,{z:F.v3.Zc});if(q){X=q[0];Y=q[1];}}
 const cx=r.left+X*r.width/fw,cy=r.top+Y*r.height/fh;const p=STU.pan||[0,0];STU.pan=[Math.round(p[0]+wr.left+wr.width/2-cx),Math.round(p[1]+wr.top+wr.height/2-cy)];amPanApply(cv);}
