function amTplBackup(id,why){const R=rmCfg();const o=R.pose&&R.pose[id];if(amTplIsEmpty(o))return;const B=R.poseBak=R.poseBak&&typeof R.poseBak==='object'?R.poseBak:{};const L=B[id]=Array.isArray(B[id])?B[id]:[];L.unshift({at:Date.now(),why:why||'',n:o.free?(o.n||''):'',free:o.free?1:0,base:o.base||'',parts:clone(o.parts||{}),pv:clone(o.pv||{})});L.length=Math.min(L.length,AM_BAK_MAX);}
