function admTestBar(){if(typeof CLOUD==='undefined'||!CLOUD.preview||typeof STORE==='undefined'||!Array.isArray(STORE.owners))return'';const ws=STORE.owners.filter(w=>w&&w.id&&!String(w.id).startsWith('__'));
 return`<label class="tiny" style="display:flex;gap:6px;align-items:center">以${H(TERMS.owner)}身分測試<select data-admtest="1" aria-label="以${H(TERMS.owner)}身分測試"><option value=""${ADMT.v?'':' selected'}>訪客（沒有鑰匙）</option><option value="*"${ADMT.v==='*'?' selected':''}>全部都有的測試${H(TERMS.owner)}</option>${ws.map(w=>`<option value="${H(w.id)}" label="${H(w.name||w.id)}（${H(w.id)}）"${ADMT.v===w.id?' selected':''}></option>`).join('')}</select></label>`;}
function admAllPayload(){const inds=[],accs={};
 STORE.species.forEach(sp=>withSpecies(sp,()=>{const p=pubCfg(sp);if(!p.on||p.tryon===0)return;const spk=spKey(sp);
  sp.inds.forEach(ind=>{const lk=pubLook(ind);const po=poseOf(ind);if(!lk&&!po)return;inds.push({sp:spk,id:ind.id,nick:ind.nick||'',sex:ind.sex,look:lk||null,pose:lk?'':po.id,pal:lk?null:palOf(ind),wear:indAcc(ind,spk).map(x=>({acc:x.acc,slot:x.slot}))});});}));
 STORE.acc.forEach(a=>{const arts=accArtsFull(a);if(!arts.length)return;accs[a.id]={id:a.id,name:a.name,kind:a.kind||'',...catPub(a,'acc'),slots:(a.slots||[]).map(k=>({k,n:wearName(k)})),species:a.species,wear:{},arts,...accColPub(a),n:1};});
 const w={id:'__admtest__',name:'管理員測試',hold:{}};(STORE.habs||[]).forEach(h=>{w.hold[habKey(h.code)]=1;});
 let rooms={};STORE.owners.push(w);try{if(typeof mrPayload==='function')rooms=mrPayload(w);}finally{const i=STORE.owners.indexOf(w);if(i>=0)STORE.owners.splice(i,1);}
 return{v:1,owner:{id:'__admtest__',name:'管理員測試（全部都有）'},inds,accs,rooms};}
function admTestSet(v){if(typeof CLOUD==='undefined'||!CLOUD.preview)return;ADMT.v=v||'';let pl=null;
 try{if(v==='*')pl=admAllPayload();else if(v){const w=STORE.owners.find(x=>x.id===v);if(w)pl=okPayload(w);}}catch(e){console.error(e);toast('準備測試資料失敗：'+((e&&e.message)||e),5000);}
 OKV.k='';OKV.kid='';OKV.err='';OKV.tried=true;OKV.data=pl?Object.assign(pl,{test:1}):null;
 if(typeof PTRY!=='undefined'){PTRY.B={};PTRY.on=[];PTRY.hist=[];PTRY.src='';if(pl){const L=okMineList();if(L.length){PTRY.src='mine';PTRY.B.mine=okBody(L[0]);okWear(L[0]);}}}
 if(typeof MR!=='undefined'&&MR.on&&typeof mrClose==='function')mrClose();
 try{if(typeof renderPublic==='function'&&PUB.site&&PUB.site.species&&PUB.site.species.length)renderPublic();}catch(e){console.warn(e);}toast(pl?`測試中：${(pl.owner&&pl.owner.name)||v}（下載的圖不附正式戳記）`:'回到訪客（沒有鑰匙）');}
function admTestClear(){if(!ADMT.v&&!(OKV.data&&OKV.data.test))return;ADMT.v='';if(OKV.data&&OKV.data.test){OKV.data=null;OKV.tried=false;}}
function tabSave(c){try{localStorage.setItem(TAB_KEY,JSON.stringify(c));}catch(e){}applyTabs();}
function themeSet(t){THEME_WANT=t==='dark'?'dark':'light';try{localStorage.setItem(THEME_KEY,THEME_WANT);}catch(e){}
 document.documentElement.setAttribute('data-theme',THEME_WANT);themeSync();
 try{renderDecor(true);decorPreview();drawPubDecor();}catch(e){}}
function saveNote(kind,msg){if(typeof document==='undefined'||!document.body)return;const b=document.body;
 if(b.classList.contains('visitor')||b.classList.contains('booting')||(typeof CLOUD!=='undefined'&&CLOUD.loading))return;
 const owner=typeof CLOUD!=='undefined'&&CLOUD.mode==='owner';
 if(kind==='cloud'&&!SAVE_NOTE_PEND)return;/* 只回報這次修改的同步結果，開頁時的「已是最新」不顯示 */
 if(kind==='local')SAVE_NOTE_PEND=owner;if(kind==='cloud'||kind==='cloudErr')SAVE_NOTE_PEND=false;
 let e=document.getElementById('savenote');if(!e){e=document.createElement('div');e.id='savenote';e.setAttribute('role','status');e.setAttribute('aria-live','polite');b.appendChild(e);}
 const t=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'});const err=kind==='fail'||kind==='cloudErr';
 e.textContent=kind==='fail'?'✗ 存檔失敗：'+(msg||'瀏覽器空間已滿或被封鎖，請到「匯入匯出」下載備份'):kind==='cloudErr'?'✗ 雲端同步失敗：'+(msg||'請到「公開與同步」查看'):kind==='cloud'?`✓ 已存檔並同步到雲端（${t}）`:owner?'✓ 已存在這個瀏覽器，正在同步雲端…':`✓ 已存檔（${t}）`;
 e.className='savenote on'+(err?' err':'')+(kind==='local'&&owner?' pend':'');clearTimeout(SAVE_NOTE_T);
 if(!err)SAVE_NOTE_T=setTimeout(()=>e.classList.remove('on'),kind==='local'&&owner?8000:2600);}
function tabIntoView(){const nav=document.getElementById('tabs');const b=nav&&nav.querySelector('button[aria-selected="true"]');if(!b||nav.scrollWidth<=nav.clientWidth)return;
 const l=b.offsetLeft-nav.offsetLeft,r=l+b.offsetWidth;if(l<nav.scrollLeft)nav.scrollLeft=Math.max(0,l-16);else if(r>nav.scrollLeft+nav.clientWidth)nav.scrollLeft=r-nav.clientWidth+16;}
function autoGrow(e){if(!e||!e.style)return;e.style.height='auto';e.style.height=Math.min(window.innerHeight*.6,e.scrollHeight+2)+'px';}
function hdr(){const s=document.getElementById('sp-cur');s.innerHTML=STORE.species.map(sp=>`<option value="${H(spKey(sp))}"${sp===S?' selected':''}>${H(spLabel(sp))}</option>`).join('');
 document.getElementById('hdrName').textContent=`${spKey(S)} · ${S.inds.length} 隻個體 · ${S.loci.length} 個基因座`;}
function blankFields(ind){if(ind.birthHab===undefined)ind.birthHab=ind.hab||'';if(!ind.epi||typeof ind.epi!=='object')ind.epi={};['folder','batch','born','buyer','contact','price','rights','memo','soldAt','nick','gen','bg','donor','marker','hab','dam','sire'].forEach(k=>{if(ind[k]==null)ind[k]='';});if(!STATUS[ind.status])ind.status='keep';
 if(!ind.np)ind.np=[];if(!ind.env)ind.env={};if(!ind.pal)ind.pal={};return ind;}
function unlockNew(ind){UI.unlocked=UI.unlocked||new Set();LOCK_SECS.forEach(([k])=>UI.unlocked.add(ind.id+'|'+k));return ind;}
function newInd(extra){const hb=(extra&&extra.hab)||defHab();return blankFields({id:nextId(UI.rollFolder,extra&&extra.bg),nick:'',sex:'F',gen:'P',bg:S.meta.defaultBg,donor:'',marker:'',hab:hb,birthHab:hb,us:newSeed(),epi:{},dam:'',sire:'',np:[],env:{},g:{},folder:UI.rollFolder,born:UI.idDate||todayISO(),status:'keep',...extra});}
async function runSpeciesAI(btn){if(!AI||AIbusy)return;AIbusy='species';document.querySelectorAll('button.ai').forEach(b=>b.disabled=true);btn.textContent='分析中…';setStat('AI 分析中…（第一次使用會先詢問是否允許，約需 1~3 分鐘）');
 let msg;try{const r=await aiSpecies();const sp=addSpecies(r);msg=`已建立 ${spLabel(sp)}（${spKey(sp)}）：${sp.loci.length} 個基因座、${sp.habitats.length} 個棲息地、${sp.inds.length} 隻創始個體，已切換為目前物種。`;UI.spFiles=[];}catch(e){msg=aiErr(e);if(e&&e.code==='not_granted')AI=null;}
 AIbusy=null;hdr();AImsg=msg;renderSpecies();setStat(msg);}
function readFile(input,cb){const f=input.files&&input.files[0];if(!f)return;const r=new FileReader();r.onload=()=>cb(String(r.result||''));r.onerror=()=>toast('無法讀取檔案');r.readAsText(f);}
function parseJSONText(t){return JSON.parse(String(t||'').replace(/^```(json)?|```$/gm,'').trim());}
function loadExt_f1100(o){if(!o||!Array.isArray(o.inds))throw new Error('不是個體 JSON');if(o.species&&o.species!==spKey(S))toast(`注意：此檔案屬於物種 ${o.species}，目前是 ${spKey(S)}`);
 [...o.inds,...(o.ancestors||[])].forEach(f=>{if(!f||!f.id||S.inds.some(i=>i.id===f.id)||UI.ext.some(i=>i.id===f.id))return;const x=blankFields(clone(f));x.g=x.g||{};normalizeG(x);x.ext=true;UI.ext.push(x);});}
