function renameInd(ind,nv){nv=String(nv||'').trim();if(!nv||nv===ind.id)return true;if(S.inds.some(i=>i!==ind&&i.id===nv)){toast(('這個'+TERMS.code+'已被使用'));return false;}
 const old=ind.id;S.inds.forEach(i=>{if(i.dam===old)i.dam=nv;if(i.sire===old)i.sire=nv;});if(UI.dam===old)UI.dam=nv;if(UI.sire===old)UI.sire=nv;if(UI.sel.delete(old))UI.sel.add(nv);ind.id=nv;UI.open=nv;return true;}
